import React, { useState, useEffect, useRef } from 'react';
import { initializeApp, getApps } from 'firebase/app';
import { 
  getFirestore, collection, doc, setDoc, addDoc, onSnapshot, 
  query, orderBy, serverTimestamp, updateDoc, increment, limit
} from 'firebase/firestore';
import { 
  getAuth, signInAnonymously, onAuthStateChanged, signInWithCustomToken
} from 'firebase/auth';
import { 
  Home, Zap, Trophy, Send, Sparkles, Heart, MessageCircle, 
  Plus, Bot, Stars, Search, Menu, X, Flame, Share2, 
  Edit3, Layout, Calculator, User, Award, Users, Settings,
  CheckCircle2, Crown, Ghost, BookOpen, GraduationCap,
  LogOut, ArrowRight, Bell, Clock, BrainCircuit, Target, 
  ThumbsUp, Smile, MoreHorizontal, ThumbsDown, Scale
} from 'lucide-react';

/**
 * --- FIREBASE CONFIGURATION ---
 */
const firebaseConfig = (typeof __firebase_config !== 'undefined') 
  ? JSON.parse(__firebase_config) 
  : { apiKey: "demo", authDomain: "demo", projectId: "demo" };

const app = getApps().length === 0 ? initializeApp(firebaseConfig) : getApps()[0];
const db = getFirestore(app);
const auth = getAuth(app);
const appId = typeof __app_id !== 'undefined' ? __app_id : 'studygram-v3-max';

/**
 * --- GEMINI API CONFIGURATION ---
 */
const apiKey = ""; // System provides key at runtime
const GEMINI_MODEL = "gemini-2.5-flash-preview-09-2025";

async function callGemini(prompt) {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent?key=${apiKey}`;
  const payload = {
    contents: [{ parts: [{ text: prompt }] }]
  };

  let retries = 0;
  const maxRetries = 3;

  while (retries < maxRetries) {
    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const data = await response.json();
      if (data.candidates && data.candidates[0].content) {
        return data.candidates[0].content.parts[0].text;
      }
      throw new Error("Invalid response from Gemini");
    } catch (e) {
      retries++;
      if (retries === maxRetries) return "Hệ thống AI đang quá tải, hãy thử lại sau nhé!";
      await new Promise(r => setTimeout(r, 1000 * Math.pow(2, retries)));
    }
  }
}

/**
 * --- DATA & UTILS ---
 */
const LEVELS = [
  { min: 0, title: "Mầm Non", icon: "🌱", color: "text-green-500" },
  { min: 100, title: "Tập Sự", icon: "🐣", color: "text-yellow-500" },
  { min: 300, title: "Học Giả", icon: "🦉", color: "text-blue-500" },
  { min: 600, title: "Giáo Sư", icon: "👓", color: "text-purple-500" },
  { min: 1000, title: "Thần Đồng", icon: "👑", color: "text-red-500" }
];

const getLevelInfo = (exp) => {
  return LEVELS.slice().reverse().find(l => exp >= l.min) || LEVELS[0];
};

/**
 * --- MAIN APP COMPONENT ---
 */

export default function App() {
  const [user, setUser] = useState(null);
  const [userData, setUserData] = useState(null);
  const [activeTab, setActiveTab] = useState('feed');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [toast, setToast] = useState(null);

  useEffect(() => {
    const initAuth = async () => {
      try {
        if (typeof __initial_auth_token !== 'undefined' && __initial_auth_token) {
          await signInWithCustomToken(auth, __initial_auth_token);
        } else {
          await signInAnonymously(auth);
        }
      } catch (error) { console.error(error); }
    };
    initAuth();

    const unsubAuth = onAuthStateChanged(auth, (u) => {
      setUser(u);
      if (u) {
        const userRef = doc(db, 'artifacts', appId, 'users', u.uid, 'profile', 'info');
        const unsubData = onSnapshot(userRef, (snap) => {
          if (snap.exists()) setUserData(snap.data());
          else setUserData(null);
          setIsLoading(false);
        });
        return () => unsubData();
      } else {
        setUserData(null);
        setIsLoading(false);
      }
    });
    return () => unsubAuth();
  }, []);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleAddExp = async (amount) => {
    if (!user || !userData) return;
    const userRef = doc(db, 'artifacts', appId, 'users', user.uid, 'profile', 'info');
    await updateDoc(userRef, { exp: increment(amount) });
    showToast(`+${amount} EXP!`, 'success');
  };

  if (isLoading) return <LoadingScreen />;
  if (user && !userData) return <Onboarding user={user} onComplete={() => setIsLoading(false)} />;

  return (
    <div className="min-h-screen bg-[#FDFCF8] text-slate-800 font-sans selection:bg-indigo-100 flex flex-col">
      {toast && <Toast toast={toast} />}

      <Sidebar 
        isOpen={sidebarOpen} 
        onClose={() => setSidebarOpen(false)} 
        userData={userData}
        setActiveTab={(tab) => { setActiveTab(tab); setSidebarOpen(false); }}
        activeTab={activeTab}
      />

      <Header 
        onOpenMenu={() => setSidebarOpen(true)} 
        userData={userData} 
        activeTab={activeTab}
      />

      {/* Main Content Area - Adjusts for different views */}
      <main className={`flex-1 flex flex-col w-full max-w-3xl mx-auto transition-all duration-300 ${activeTab === 'tutor' ? 'h-[calc(100vh-64px-80px)]' : 'p-4 md:p-6 pb-24 mt-16'}`}>
        {activeTab === 'feed' && (
          <Feed user={user} userData={userData} onExp={handleAddExp} showToast={showToast} />
        )}
        {activeTab === 'tutor' && (
          <AITutor user={user} userData={userData} onExp={handleAddExp} />
        )}
        {activeTab === 'focus' && (
          <FocusZone onExp={handleAddExp} showToast={showToast} />
        )}
        {activeTab === 'quiz' && (
          <QuizArena onExp={handleAddExp} showToast={showToast} />
        )}
        {activeTab === 'rank' && (
          <Leaderboard currentUid={user?.uid} />
        )}
        {activeTab === 'profile' && (
          <Profile user={user} userData={userData} />
        )}
      </main>

      <BottomNav activeTab={activeTab} setActiveTab={setActiveTab} />
    </div>
  );
}

/**
 * --- SUB-VIEWS ---
 */

// 1. Onboarding (Giữ nguyên)
const Onboarding = ({ user, onComplete }) => {
  const [name, setName] = useState('');
  const handleSubmit = async () => {
    if (!name.trim()) return;
    const profile = {
      uid: user.uid,
      name: name,
      avatar: `https://api.dicebear.com/9.x/notionists/svg?seed=${name}`,
      exp: 0,
      bio: 'Học giả tiềm năng',
      joinedAt: serverTimestamp()
    };
    await setDoc(doc(db, 'artifacts', appId, 'users', user.uid, 'profile', 'info'), profile);
    onComplete();
  };
  return (
    <div className="fixed inset-0 bg-white z-[100] flex flex-col items-center justify-center p-6 text-center">
      <div className="w-20 h-20 bg-indigo-600 rounded-3xl mb-6 flex items-center justify-center text-white shadow-lg"><BookOpen size={36} /></div>
      <h1 className="text-2xl font-black mb-6 text-slate-800">Chào mừng tới StudyGram</h1>
      <input value={name} onChange={e => setName(e.target.value)} className="w-full max-w-xs p-4 bg-slate-50 border-2 rounded-2xl mb-4 text-center outline-none focus:border-indigo-500" placeholder="Tên của bạn..." />
      <button onClick={handleSubmit} disabled={!name} className="w-full max-w-xs py-4 bg-indigo-600 text-white rounded-2xl font-bold">Bắt đầu</button>
    </div>
  );
};

// 2. Feed & Post Card (Giữ nguyên các logic cũ)
const Feed = ({ user, userData, onExp, showToast }) => {
  const [posts, setPosts] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    const q = query(collection(db, 'artifacts', appId, 'public', 'data', 'posts'), orderBy('createdAt', 'desc'), limit(30));
    return onSnapshot(q, (snap) => setPosts(snap.docs.map(d => ({ id: d.id, ...d.data() }))));
  }, []);

  return (
    <div className="space-y-6">
      <div onClick={() => setIsModalOpen(true)} className="bg-white p-4 rounded-3xl border border-slate-100 shadow-sm flex items-center gap-4 cursor-pointer">
        <img src={userData?.avatar} className="w-10 h-10 rounded-full bg-slate-100" />
        <div className="flex-1 text-slate-400 text-sm">Hôm nay bạn học gì?</div>
        <Plus className="text-indigo-600" />
      </div>
      {posts.map(post => <PostCard key={post.id} post={post} user={user} userData={userData} />)}
      {isModalOpen && <CreatePostModal onClose={() => setIsModalOpen(false)} onSubmit={async (content, cat) => {
        await addDoc(collection(db, 'artifacts', appId, 'public', 'data', 'posts'), {
          uid: user.uid, userName: userData.name, avatar: userData.avatar, content, category: cat, createdAt: serverTimestamp(), likes: []
        });
        onExp(20);
        setIsModalOpen(false);
      }} userData={userData} />}
    </div>
  );
};

const PostCard = ({ post, user, userData }) => {
  const [likes, setLikes] = useState(post.likes || []);
  const [aiAnalysis, setAiAnalysis] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleLike = async () => {
    const newLikes = likes.includes(user.uid) ? likes.filter(id => id !== user.uid) : [...likes, user.uid];
    setLikes(newLikes);
    await updateDoc(doc(db, 'artifacts', appId, 'public', 'data', 'posts', post.id), { likes: newLikes });
  };

  const analyze = async () => {
    if (aiAnalysis) return;
    setLoading(true);
    const res = await callGemini(`Nhận xét ngắn gọn về bài đăng kiến thức này bằng tiếng Việt: "${post.content}"`);
    setAiAnalysis(res);
    setLoading(false);
  };

  return (
    <div className="bg-white rounded-3xl p-5 border border-slate-100 shadow-sm">
      <div className="flex gap-3 mb-4">
        <img src={post.avatar} className="w-10 h-10 rounded-xl" />
        <div>
          <h4 className="font-bold text-sm">{post.userName}</h4>
          <span className="text-[10px] bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded-full font-bold">{post.category}</span>
        </div>
      </div>
      <p className="text-slate-700 text-sm mb-4">{post.content}</p>
      {aiAnalysis && <div className="p-3 bg-indigo-50 rounded-2xl mb-4 text-xs italic text-indigo-800">AI: {aiAnalysis}</div>}
      <div className="flex gap-4 pt-3 border-t border-slate-50">
        <button onClick={handleLike} className={`flex items-center gap-1 text-xs font-bold ${likes.includes(user.uid) ? 'text-pink-500' : 'text-slate-400'}`}>
          <Heart size={16} className={likes.includes(user.uid) ? 'fill-pink-500' : ''} /> {likes.length}
        </button>
        <button onClick={analyze} className="ml-auto text-xs font-bold text-indigo-400 hover:text-indigo-600 flex items-center gap-1">
          {loading ? "Đang nghĩ..." : <><Sparkles size={16}/> Phân tích AI</>}
        </button>
      </div>
    </div>
  );
};

// 3. --- GIA SƯ AI (ĐÃ SỬA CHỖ GỬI TIN NHẮN) ---
const AITutor = ({ user, userData, onExp }) => {
    const [messages, setMessages] = useState([
        { role: 'ai', text: `Chào ${userData?.name}! Bạn cần mình hỗ trợ giải đáp bài tập hay kiến thức nào không?` }
    ]);
    const [input, setInput] = useState('');
    const [isTyping, setIsTyping] = useState(false);
    const chatEndRef = useRef(null);

    const scrollToBottom = () => {
        chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        scrollToBottom();
    }, [messages, isTyping]);

    const handleSend = async () => {
        if (!input.trim() || isTyping) return;

        const userText = input.trim();
        setInput('');
        setMessages(prev => [...prev, { role: 'user', text: userText }]);
        setIsTyping(true);

        const prompt = `Bạn là một gia sư AI hỗ trợ học sinh Việt Nam. Hãy trả lời câu hỏi sau một cách thông minh, dễ hiểu, hài hước: "${userText}"`;
        const reply = await callGemini(prompt);

        setMessages(prev => [...prev, { role: 'ai', text: reply }]);
        setIsTyping(false);
        onExp(5); 
    };

    return (
        <div className="flex flex-col h-full bg-slate-50 mt-16 md:mt-0">
            {/* Header chat - Cố định trên cùng của vùng chat */}
            <div className="bg-white p-3 border-b flex items-center gap-3">
                <div className="w-10 h-10 bg-indigo-100 rounded-full flex items-center justify-center text-indigo-600">
                    <Bot size={24} />
                </div>
                <div>
                    <h3 className="font-bold text-sm">Gia Sư Học Tập AI</h3>
                    <div className="flex items-center gap-1">
                        <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                        <span className="text-[10px] text-slate-500 font-medium">Đang trực tuyến</span>
                    </div>
                </div>
            </div>

            {/* Vùng hiển thị tin nhắn - Cuộn được */}
            <div className="flex-1 overflow-y-auto p-4 space-y-4">
                {messages.map((m, i) => (
                    <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`max-w-[85%] p-3 rounded-2xl text-sm leading-relaxed ${
                            m.role === 'user' 
                            ? 'bg-indigo-600 text-white rounded-tr-none' 
                            : 'bg-white border text-slate-700 rounded-tl-none shadow-sm'
                        }`}>
                            {m.text}
                        </div>
                    </div>
                ))}
                {isTyping && (
                    <div className="flex justify-start">
                        <div className="bg-white border p-3 rounded-2xl rounded-tl-none shadow-sm flex gap-1">
                            <div className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce"></div>
                            <div className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                            <div className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                        </div>
                    </div>
                )}
                <div ref={chatEndRef} />
            </div>

            {/* --- THANH NHẬN GỬI TIN NHẮN - ĐÃ ĐƯỢC CẢI THIỆN --- */}
            <div className="p-4 bg-white border-t border-slate-100 safe-area-bottom">
                <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-2xl border border-slate-200 focus-within:border-indigo-400 focus-within:bg-white transition-all">
                    <input 
                        value={input}
                        onChange={e => setInput(e.target.value)}
                        onKeyDown={e => e.key === 'Enter' && handleSend()}
                        placeholder="Hỏi bài tập hoặc tâm sự..."
                        className="flex-1 bg-transparent px-2 py-1 outline-none text-sm"
                    />
                    <button 
                        onClick={handleSend} 
                        disabled={!input.trim() || isTyping}
                        className={`w-10 h-10 flex items-center justify-center rounded-xl transition-all ${
                            input.trim() && !isTyping ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-200 text-slate-400'
                        }`}
                    >
                        <Send size={18} />
                    </button>
                </div>
                <p className="text-[10px] text-center text-slate-400 mt-2">AI có thể đưa ra câu trả lời chưa chính xác, hãy kiểm tra lại nhé!</p>
            </div>
        </div>
    );
};

// 4. Các UI cơ bản khác (Giữ nguyên)
const FocusZone = ({ onExp, showToast }) => {
    const [seconds, setSeconds] = useState(25 * 60);
    const [active, setActive] = useState(false);
    useEffect(() => {
        let itv;
        if (active && seconds > 0) itv = setInterval(() => setSeconds(s => s - 1), 1000);
        else if (seconds === 0) { setActive(false); onExp(50); showToast("Tuyệt vời! +50 EXP"); }
        return () => clearInterval(itv);
    }, [active, seconds]);
    return (
        <div className="flex flex-col items-center justify-center h-full gap-8">
            <div className="text-7xl font-black text-indigo-600 font-mono">
                {Math.floor(seconds / 60)}:{String(seconds % 60).padStart(2, '0')}
            </div>
            <button onClick={() => setActive(!active)} className="px-12 py-4 bg-indigo-600 text-white rounded-3xl font-black shadow-xl">
                {active ? "DỪNG LẠI" : "BẮT ĐẦU TẬP TRUNG"}
            </button>
        </div>
    );
};

const QuizArena = ({ onExp, showToast }) => (
    <div className="flex flex-col items-center justify-center h-full gap-4 p-6 text-center">
        <div className="w-20 h-20 bg-yellow-100 rounded-full flex items-center justify-center text-yellow-600 mb-2"><Trophy size={40}/></div>
        <h2 className="text-xl font-black">Quiz Arena</h2>
        <p className="text-slate-500 text-sm">Tham gia đấu trường tri thức với các bạn cùng lớp để nhận quà!</p>
        <button className="px-8 py-3 bg-slate-800 text-white rounded-2xl font-bold mt-4" onClick={() => showToast("Sắp ra mắt!")}>Tìm đối thủ</button>
    </div>
);

const Leaderboard = () => (
    <div className="space-y-4">
        <h2 className="text-xl font-black flex items-center gap-2"><Crown className="text-yellow-500" /> Top Học Giả</h2>
        <div className="bg-white rounded-3xl p-4 border space-y-4">
            {[1, 2, 3].map(i => (
                <div key={i} className="flex items-center gap-4 p-2">
                    <div className="w-8 h-8 font-black text-slate-400">#{i}</div>
                    <div className="w-10 h-10 bg-slate-100 rounded-full"></div>
                    <div className="flex-1 font-bold text-sm">Học viên ẩn danh</div>
                    <div className="text-indigo-600 font-black">1,200 XP</div>
                </div>
            ))}
        </div>
    </div>
);

const Profile = ({ userData }) => (
    <div className="text-center space-y-4">
        <img src={userData.avatar} className="w-24 h-24 rounded-full mx-auto border-4 border-white shadow-lg" />
        <h2 className="text-2xl font-black">{userData.name}</h2>
        <div className="inline-block px-4 py-2 bg-indigo-50 text-indigo-600 rounded-full font-bold text-sm">
            {getLevelInfo(userData.exp).title} • {userData.exp} EXP
        </div>
        <div className="grid grid-cols-2 gap-4 mt-8">
            <div className="bg-white p-4 rounded-3xl border">
                <div className="text-2xl mb-1">🔥</div>
                <div className="text-xs font-bold text-slate-400 uppercase">Ngày liên tiếp</div>
                <div className="text-lg font-black">5 ngày</div>
            </div>
            <div className="bg-white p-4 rounded-3xl border">
                <div className="text-2xl mb-1">📚</div>
                <div className="text-xs font-bold text-slate-400 uppercase">Bài đã giải</div>
                <div className="text-lg font-black">12 bài</div>
            </div>
        </div>
    </div>
);

const Header = ({ onOpenMenu, activeTab }) => (
    <header className="fixed top-0 left-0 right-0 h-16 bg-white/80 backdrop-blur-md border-b z-40 flex items-center justify-between px-4">
        <button onClick={onOpenMenu} className="p-2"><Menu /></button>
        <h1 className="font-black text-indigo-600 text-lg uppercase tracking-tight">
            {activeTab === 'feed' ? 'StudyGram' : 
             activeTab === 'tutor' ? 'AI Tutor' :
             activeTab === 'focus' ? 'Focus' : 
             activeTab === 'quiz' ? 'Arena' : 
             activeTab === 'rank' ? 'Top' : 'Hồ sơ'}
        </h1>
        <button className="p-2 text-slate-400"><Bell size={20}/></button>
    </header>
);

