import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface UserProfile {
  uid: string;
  name: string;
  avatar: string;
  exp: number;
  bio: string;
  joinedAt: number;
  streak: number;
  completedQuizzes: number;
}

export interface Post {
  id: string;
  uid: string;
  userName: string;
  avatar: string;
  content: string;
  category: string;
  createdAt: number;
  likes: string[];
  aiAnalysis?: string;
}

export interface Message {
  role: 'ai' | 'user';
  text: string;
  timestamp: number;
}

export enum AppTab {
  FEED = 'feed',
  TUTOR = 'tutor',
  FOCUS = 'focus',
  QUIZ = 'quiz',
  RANK = 'rank',
  PROFILE = 'profile'
}

export interface LevelInfo {
  min: number;
  title: string;
  icon: string;
  color: string;
}

import { LevelInfo } from './types';

export const APP_ID = 'studygram-v3-max';

export const LEVELS: LevelInfo[] = [
  { min: 0, title: "Mầm Non", icon: "🌱", color: "text-green-500" },
  { min: 100, title: "Tập Sự", icon: "🐣", color: "text-yellow-500" },
  { min: 300, title: "Học Giả", icon: "🦉", color: "text-blue-500" },
  { min: 600, title: "Giáo Sư", icon: "👓", color: "text-purple-500" },
  { min: 1000, title: "Thần Đồng", icon: "👑", color: "text-red-500" }
];

export const STUDY_CATEGORIES = [
  "Toán học", "Ngữ văn", "Ngoại ngữ", "Vật lý", "Hóa học", "Lịch sử", "Địa lý", "Tin học", "Khác"
];

export const getLevelInfo = (exp: number): LevelInfo => {
  return [...LEVELS].reverse().find(l => exp >= l.min) || LEVELS[0];
};

import { GoogleGenAI } from "@google/genai";

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
};

export const callGeminiText = async (prompt: string, systemInstruction?: string): Promise<string> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: systemInstruction || "Bạn là một trợ lý học tập thông minh, thân thiện và hài hước cho học sinh Việt Nam.",
        temperature: 0.7,
      },
    });
    return response.text || "Xin lỗi, mình đang gặp chút trục trặc trong lúc suy nghĩ.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Hệ thống AI đang bận, bạn thử lại sau nhé!";
  }
};

export const analyzeStudyPost = async (content: string): Promise<string> => {
  const prompt = `Hãy nhận xét ngắn gọn (dưới 50 từ) về bài đăng kiến thức này bằng tiếng Việt, mang tính khích lệ và bổ sung thêm 1 thông tin thú vị nếu có thể: "${content}"`;
  return callGeminiText(prompt, "Bạn là một giáo sư vui tính chuyên nhận xét các bài học của sinh viên.");
};

export const getTutorResponse = async (userMessage: string): Promise<string> => {
  return callGeminiText(userMessage, "Bạn là Gia Sư Học Tập AI. Nhiệm vụ của bạn là giải đáp các thắc mắc về bài vở, kiến thức một cách ngắn gọn, súc tích và dễ hiểu. Hãy sử dụng ngôn ngữ trẻ trung, gần gũi với học sinh Việt Nam.");
};

