  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedChat = localStorage.getItem('studygram_chat');
    if (savedChat) {
      setMessages(JSON.parse(savedChat));
    } else {
      setMessages([
        { 
          role: 'ai', 
          text: `Chào ${userData.name}! Mình là Gia Sư Học Tập AI. Bạn có bài tập nào khó hay cần giải thích kiến thức gì không?`,
          timestamp: Date.now()
        }
      ]);
    }
  }, [userData.name]);

  useEffect(() => {
    localStorage.setItem('studygram_chat', JSON.stringify(messages));
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userText = input.trim();
    setInput('');
    const userMsg: Message = { role: 'user', text: userText, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setIsTyping(true);

    const replyText = await getTutorResponse(userText);

    const aiMsg: Message = { role: 'ai', text: replyText, timestamp: Date.now() };
    setMessages(prev => [...prev, aiMsg]);
    setIsTyping(false);
    onExp(5); 
  };

  const clearChat = () => {
    if (window.confirm('Bạn có muốn xóa toàn bộ lịch sử trò chuyện không?')) {
      setMessages([{ 
        role: 'ai', 
        text: `Chào ${userData.name}! Mình đã sẵn sàng cho những câu hỏi mới.`,
        timestamp: Date.now()
      }]);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50">
      {/* Header chat */}
      <div className="bg-white p-4 border-b flex items-center justify-between shadow-sm z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-full flex items-center justify-center text-white shadow-md">
            <Bot size={24} />
          </div>
          <div>
            <h3 className="font-bold text-sm text-slate-800">Gia Sư Học Tập AI</h3>
            <div className="flex items-center gap-1.5">
              <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
              <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Đang trực tuyến</span>
            </div>
          </div>
        </div>
        <button 
          onClick={clearChat}
          className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
          title="Xóa lịch sử"
        >
          <Trash2 size={20} />
        </button>
      </div>

      {/* Message Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-3xl text-sm leading-relaxed shadow-sm animate-slide-in ${
              m.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-tr-none' 
                : 'bg-white border border-slate-100 text-slate-700 rounded-tl-none'
            }`}>
              {m.text}
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-start">
            <div className="bg-white border border-slate-100 p-4 rounded-3xl rounded-tl-none shadow-sm flex gap-1.5">
              <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce"></div>
              <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
              <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
            </div>
          </div>
        )}
        <div ref={chatEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-4 bg-white border-t border-slate-100 safe-area-bottom">
        <div className="flex items-center gap-3 bg-slate-50 p-2 rounded-[1.5rem] border border-slate-100 focus-within:border-indigo-400 focus-within:bg-white transition-all shadow-inner">
          <input 
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSend()}
            placeholder="Hỏi bài tập Toán, Văn, Anh..."
            className="flex-1 bg-transparent px-3 py-2 outline-none text-sm font-medium"
          />
          <button 
            onClick={handleSend} 
            disabled={!input.trim() || isTyping}
            className={`w-11 h-11 flex items-center justify-center rounded-2xl transition-all active:scale-95 ${
              input.trim() && !isTyping 
                ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' 
                : 'bg-slate-200 text-slate-400'
            }`}
          >
            <Send size={20} />
          </button>
        </div>
        <p className="text-[9px] text-center text-slate-400 mt-2 font-bold uppercase tracking-widest">
          AI có thể phản hồi chưa chính xác, hãy kiểm tra lại nhé!
        </p>
      </div>
    </div>
  );
};

