  const isLiked = post.likes.includes(currentUserId);
  const [showComments, setShowComments] = useState(false);
  const [commentInput, setCommentInput] = useState('');

  const handleSendComment = () => {
    if (!commentInput.trim()) return;
    onComment(commentInput.trim());
    setCommentInput('');
  };

  return (
    <div className="bg-white rounded-3xl p-5 border border-slate-100 shadow-sm animate-slide-in">
      <div className="flex justify-between items-start mb-4">
        <div className="flex gap-3">
          <img src={post.avatar} className="w-10 h-10 rounded-xl bg-slate-50 border border-slate-100" />
          <div>
            <h4 className="font-bold text-sm text-slate-800">{post.userName}</h4>
            <div className="flex items-center gap-2 mt-0.5">
              <span className="text-[10px] bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded-full font-bold">
                {post.category}
              </span>
              <span className="text-[10px] text-slate-400 font-medium">
                {new Date(post.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>
            </div>
          </div>
        </div>
      </div>

      <p className="text-slate-700 text-sm leading-relaxed mb-4 whitespace-pre-wrap">
        {post.content}
      </p>

      {post.aiAnalysis && (
        <div className="p-4 bg-gradient-to-br from-indigo-50 to-white border border-indigo-100 rounded-2xl mb-4 text-xs italic text-indigo-800 shadow-inner">
          <div className="flex items-center gap-2 mb-1.5 not-italic font-bold text-indigo-600 uppercase tracking-wider text-[9px]">
            <Sparkles size={12} /> AI Insight
          </div>
          {post.aiAnalysis}
        </div>
      )}

      <div className="flex items-center gap-6 pt-3 border-t border-slate-50">
        <button 
          onClick={onLike}
          className={`flex items-center gap-1.5 text-xs font-bold transition-all active:scale-90 ${
            isLiked ? 'text-pink-500' : 'text-slate-400 hover:text-slate-600'
          }`}
        >
          <Heart size={18} className={isLiked ? 'fill-pink-500' : ''} />
          {post.likes.length > 0 && post.likes.length}
        </button>

        <button 
          onClick={() => setShowComments(!showComments)}
          className={`flex items-center gap-1.5 text-xs font-bold transition-all ${
            showComments ? 'text-indigo-600' : 'text-slate-400 hover:text-slate-600'
          }`}
        >
          <MessageCircle size={18} />
          {post.comments?.length > 0 && post.comments.length}
        </button>

        <button 
          onClick={onAnalyze}
          disabled={!!post.aiAnalysis}
          className={`ml-auto flex items-center gap-1.5 text-xs font-bold transition-all px-3 py-1.5 rounded-lg ${
            post.aiAnalysis 
              ? 'text-indigo-300 cursor-not-allowed' 
              : 'text-indigo-500 hover:bg-indigo-50 active:scale-95'
          }`}
        >
          <Sparkles size={16} /> 
          {post.aiAnalysis ? 'Đã phân tích' : 'Phân tích AI'}
        </button>
      </div>

      {/* Comment Section */}
      {showComments && (
        <div className="mt-4 pt-4 border-t border-slate-50 space-y-4 animate-slide-in">
          <div className="space-y-3">
            {post.comments?.map((comment) => (
              <div key={comment.id} className="flex gap-3">
                <img src={comment.avatar} className="w-8 h-8 rounded-lg bg-slate-50 border border-slate-100 shrink-0" />
                <div className="bg-slate-50 p-3 rounded-2xl rounded-tl-none flex-1">
                  <div className="flex justify-between items-center mb-1">
                    <span className="text-[11px] font-bold text-slate-800">{comment.userName}</span>
                    <span className="text-[9px] text-slate-400">{new Date(comment.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  </div>
                  <p className="text-xs text-slate-600 leading-normal">{comment.content}</p>
                </div>
              </div>
            ))}
          </div>

          <div className="flex items-center gap-2">
            <input 
              value={commentInput}
              onChange={(e) => setCommentInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSendComment()}
              placeholder="Viết bình luận..."
              className="flex-1 bg-slate-50 border-none outline-none px-4 py-2 rounded-xl text-xs font-medium focus:ring-1 focus:ring-indigo-100"
            />
            <button 
              onClick={handleSendComment}
              disabled={!commentInput.trim()}
              className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-xl disabled:opacity-30 transition-all active:scale-90"
            >
              <Send size={18} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

