import React, { useState, useEffect, useRef } from 'react';
import { Bot, Send, Sparkles, Trash2, Camera, Image as ImageIcon, X } from 'lucide-react';
import { Message, UserProfile } from '../types';
import { getTutorResponse, analyzeStudyImage } from '../services/geminiService';

interface AITutorProps {
  userData: UserProfile;
  onExp: (amount: number) => void;
}

const AITutor: React.FC<AITutorProps> = ({ userData, onExp }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedChat = localStorage.getItem('studygram_chat');
    if (savedChat) {
      setMessages(JSON.parse(savedChat));
    } else {
      setMessages([
        { 
          role: 'ai', 
          text: `Chào ${userData.name}! Mình là Gia Sư Học Tập AI Perfect. 🎓\n\nNgoài trả lời câu hỏi, mình còn có thể giải đề qua hình ảnh. Bạn chỉ cần chụp ảnh bài tập và gửi cho mình nhé!`,
          timestamp: Date.now()
        }
      ]);
    }
  }, [userData.name]);

  useEffect(() => {
    localStorage.setItem('studygram_chat', JSON.stringify(messages));
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  const handleSend = async () => {
    if ((!input.trim() && !selectedImage) || isTyping) return;

    const userText = input.trim();
    const imageToProcess = selectedImage;

    setInput('');
    setSelectedImage(null);

    const userMsg: Message = { 
      role: 'user', 
      text: imageToProcess ? `[Ảnh bài tập] ${userText}` : userText, 
      timestamp: Date.now() 
    };

    setMessages(prev => [...prev, userMsg]);
    setIsTyping(true);

    let replyText = "";
    if (imageToProcess) {
      replyText = await analyzeStudyImage(imageToProcess, userText);
    } else {
      replyText = await getTutorResponse(userText);
    }

    const aiMsg: Message = { role: 'ai', text: replyText, timestamp: Date.now() };
    setMessages(prev => [...prev, aiMsg]);
    setIsTyping(false);
    onExp(10); 
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearChat = () => {
    if (window.confirm('Bạn có muốn xóa toàn bộ lịch sử trò chuyện không?')) {
      setMessages([{ 
        role: 'ai', 
        text: `Chào ${userData.name}! Mình đã sẵn sàng cho những câu hỏi mới.`,
        timestamp: Date.now()
      }]);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#F4F7FF]/50">
      {/* Header chat */}
      <div className="bg-white/70 backdrop-blur-md p-4 border-b flex items-center justify-between shadow-sm z-10">
        <div className="flex items-center gap-4">
          <div className="relative">
              <div className="w-12 h-12 bg-indigo-600 rounded-[1.25rem] flex items-center justify-center text-white shadow-xl shadow-indigo-100 animate-float">
                <Bot size={28} />
              </div>
              <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 border-2 border-white rounded-full"></div>
          </div>
          <div>
            <h3 className="font-black text-sm text-slate-800 tracking-tight">Gia Sư AI Perfect</h3>
            <div className="flex items-center gap-1.5 mt-0.5">
              <span className="text-[9px] text-indigo-600 font-black uppercase tracking-widest">Đa phương thức</span>
            </div>
          </div>
        </div>
        <button 
          onClick={clearChat}
          className="p-3 text-slate-400 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-all"
        >
          <Trash2 size={20} />
        </button>
      </div>

      {/* Message Area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[88%] p-5 rounded-[2rem] text-sm leading-relaxed shadow-sm animate-slide-in font-medium ${
              m.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-tr-none shadow-indigo-100' 
                : 'bg-white border border-slate-100 text-slate-700 rounded-tl-none'
            }`}>
              {m.text}
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-start">
            <div className="bg-white border border-slate-100 p-5 rounded-[2rem] rounded-tl-none shadow-sm flex gap-2">
              <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce"></div>
              <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
              <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
            </div>
          </div>
        )}
        <div ref={chatEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-4 bg-white/70 backdrop-blur-md border-t border-slate-100 safe-area-bottom">
        {selectedImage && (
            <div className="mb-4 relative inline-block animate-slide-in">
                <img src={selectedImage} className="w-24 h-24 object-cover rounded-2xl border-4 border-white shadow-xl" />
                <button 
                    onClick={() => setSelectedImage(null)}
