import React, { useState, useEffect } from 'react';
import { Clock, Play, Pause, RotateCcw, Award, Music, Volume2, Waves } from 'lucide-react';

interface FocusZoneProps {
  onExp: (amount: number) => void;
  showToast: (message: string) => void;
}

const FocusZone: React.FC<FocusZoneProps> = ({ onExp, showToast }) => {
  const [seconds, setSeconds] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [mode, setMode] = useState<'study' | 'break'>('study');
  const [isLofiOn, setIsLofiOn] = useState(false);

  useEffect(() => {
    let interval: any = null;
    if (isActive && seconds > 0) {
      interval = setInterval(() => {
        setSeconds(s => s - 1);
      }, 1000);
    } else if (seconds === 0) {
      setIsActive(false);
      // @ts-ignore
      window.confetti({ particleCount: 150, spread: 100, origin: { y: 0.7 } });

      if (mode === 'study') {
        onExp(60);
        showToast("Tập trung xuất sắc! +60 EXP 🌟");
        setMode('break');
        setSeconds(5 * 60);
      } else {
        showToast("Thời gian nghỉ đã hết. Trở lại bàn học thôi!");
        setMode('study');
        setSeconds(25 * 60);
      }
    }
    return () => clearInterval(interval);
  }, [isActive, seconds, mode, onExp, showToast]);

  const toggleTimer = () => setIsActive(!isActive);

  const resetTimer = () => {
    setIsActive(false);
    setSeconds(mode === 'study' ? 25 * 60 : 5 * 60);
  };

  const setTimerMode = (newMode: 'study' | 'break') => {
    setIsActive(false);
    setMode(newMode);
    setSeconds(newMode === 'study' ? 25 * 60 : 5 * 60);
  };

  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const total = mode === 'study' ? 25 * 60 : 5 * 60;
  const progress = ((total - seconds) / total) * 100;

  return (
    <div className="flex flex-col items-center justify-center h-full gap-10 py-8 animate-slide-in max-w-lg mx-auto">
      <div className="glass p-2 rounded-[2rem] shadow-sm border-white flex gap-1">
        <button 
          onClick={() => setTimerMode('study')}
          className={`px-8 py-3 rounded-[1.5rem] text-xs font-black transition-all ${mode === 'study' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-400 hover:bg-slate-50'}`}
        >
          HỌC TẬP
        </button>
        <button 
          onClick={() => setTimerMode('break')}
          className={`px-8 py-3 rounded-[1.5rem] text-xs font-black transition-all ${mode === 'break' ? 'bg-teal-500 text-white shadow-xl shadow-teal-100' : 'text-slate-400 hover:bg-slate-50'}`}
        >
          NGHỈ NGƠI
        </button>
      </div>

      <div className="relative flex items-center justify-center w-80 h-80 group">
        <div className={`absolute inset-0 rounded-full blur-3xl opacity-20 transition-all duration-1000 ${isActive ? (mode === 'study' ? 'bg-indigo-500' : 'bg-teal-500 animate-pulse') : 'bg-slate-300'}`}></div>

        {/* Progress Ring */}
        <svg className="absolute w-full h-full -rotate-90">
          <circle 
            cx="160" cy="160" r="145" 
            className="fill-none stroke-slate-100 stroke-[12]"
          />
          <circle 
            cx="160" cy="160" r="145" 
            className={`fill-none stroke-[12] transition-all duration-1000 ease-linear ${mode === 'study' ? 'stroke-indigo-600' : 'stroke-teal-500'}`}
            strokeDasharray={911}
            strokeDashoffset={911 - (911 * progress) / 100}
            strokeLinecap="round"
          />
        </svg>

        <div className="text-center z-10">
          <div className="text-7xl font-black text-slate-800 font-mono tracking-tighter mb-2 transition-all group-hover:scale-110">
            {formatTime(seconds)}
          </div>
          <div className={`text-[10px] font-black uppercase tracking-[0.3em] ${mode === 'study' ? 'text-indigo-400' : 'text-teal-400'}`}>
            {isActive ? <span className="flex items-center gap-1 justify-center"><Waves size={12} className="animate-pulse" /> Focus Flow</span> : 'Deep Work Zone'}
          </div>
        </div>
      </div>

      <div className="flex items-center gap-6">
        <button 
          onClick={resetTimer}
          className="p-5 bg-white text-slate-400 rounded-3xl border border-slate-100 shadow-sm hover:text-slate-600 hover:shadow-md transition-all active:scale-90"
        >
          <RotateCcw size={28} />
        </button>

        <button 
          onClick={toggleTimer} 
          className={`px-16 py-6 rounded-[2.5rem] font-black text-white shadow-2xl transition-all active:scale-95 flex items-center gap-4 text-lg ${
            isActive ? 'bg-slate-800 shadow-slate-200' : 'bg-indigo-600 shadow-indigo-100 hover:scale-105'
          }`}
        >
          {isActive ? <><Pause size={28} fill="currentColor" /> DỪNG</> : <><Play size={28} fill="currentColor" /> BẮT ĐẦU</>}
        </button>

        <button 
          onClick={() => setIsLofiOn(!isLofiOn)}
          className={`p-5 rounded-3xl border transition-all active:scale-90 ${isLofiOn ? 'bg-indigo-50 border-indigo-200 text-indigo-600 shadow-inner' : 'bg-white border-slate-100 text-slate-400 shadow-sm'}`}
        >
          <Music size={28} className={isLofiOn ? 'animate-bounce' : ''} />
        </button>
      </div>

      <div className="glass p-6 rounded-[2.5rem] border-white shadow-sm w-full text-center flex items-center justify-between">
          <div className="text-left">
            <h4 className="font-black text-slate-800 text-sm uppercase tracking-tight">Lo-fi Chill Beats</h4>
            <p className="text-[10px] text-slate-400 font-bold uppercase mt-0.5">{isLofiOn ? 'Đang phát...' : 'Đã tắt nhạc'}</p>
          </div>
          <div className="flex gap-1">
              {[1,2,3,4,5].map(i => (
                  <div key={i} className={`w-1 bg-indigo-200 rounded-full transition-all duration-300 ${isLofiOn ? 'h-4 animate-pulse' : 'h-1'}`} style={{ animationDelay: `${i * 0.1}s` }}></div>
              ))}
          </div>
      </div>
    </div>
  );
};

