  );
};

// @ts-ignore
const X = ({ size }) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>;

export default FocusZone;

import React, { useState, useEffect } from 'react';
import { Clock, Play, Pause, RotateCcw, Award, Music, Waves, ChevronRight, X, Youtube, Search, Link as LinkIcon, History, Zap } from 'lucide-react';

interface FocusZoneProps {
  onExp: (amount: number) => void;
  showToast: (message: string) => void;
}

interface StudyRadio {
  id: string;
  title: string;
  youtubeId: string;
  thumbnail: string;
}

const PRESET_RADIOS: StudyRadio[] = [
  { id: 'lofi', title: 'Lofi Girl', youtubeId: 'jfKfPfyJRdk', thumbnail: 'https://img.youtube.com/vi/jfKfPfyJRdk/0.jpg' },
  { id: 'piano', title: 'Classical Piano', youtubeId: '4oZ8I9yS5-M', thumbnail: 'https://img.youtube.com/vi/4oZ8I9yS5-M/0.jpg' },
  { id: 'rain', title: 'Rainy Cafe', youtubeId: 'v8v1Uv_fE8s', thumbnail: 'https://img.youtube.com/vi/v8v1Uv_fE8s/0.jpg' },
];

const FocusZone: React.FC<FocusZoneProps> = ({ onExp, showToast }) => {
  const [seconds, setSeconds] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [mode, setMode] = useState<'study' | 'break'>('study');
  const [activeRadio, setActiveRadio] = useState<StudyRadio | null>(null);
  const [showPlayer, setShowPlayer] = useState(false);
  const [customUrl, setCustomUrl] = useState('');
  const [history, setHistory] = useState<StudyRadio[]>([]);

  useEffect(() => {
    let interval: any = null;
    if (isActive && seconds > 0) {
      interval = setInterval(() => {
        setSeconds(s => s - 1);
      }, 1000);
    } else if (seconds === 0) {
      setIsActive(false);
      // @ts-ignore
      window.confetti({ particleCount: 150, spread: 100, origin: { y: 0.7 } });

      if (mode === 'study') {
        onExp(60);
        showToast("Tập trung xuất sắc! +60 EXP 🌟");
        setMode('break');
        setSeconds(5 * 60);
      } else {
        showToast("Thời gian nghỉ đã hết. Trở lại bàn học thôi!");
        setMode('study');
        setSeconds(25 * 60);
      }
    }
    return () => clearInterval(interval);
  }, [isActive, seconds, mode, onExp, showToast]);

  const toggleTimer = () => setIsActive(!isActive);

  const resetTimer = () => {
    setIsActive(false);
    setSeconds(mode === 'study' ? 25 * 60 : 5 * 60);
  };

  const setTimerMode = (newMode: 'study' | 'break') => {
    setIsActive(false);
    setMode(newMode);
    setSeconds(newMode === 'study' ? 25 * 60 : 5 * 60);
  };

  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const extractYoutubeId = (url: string) => {
    const regex = /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/i;
    const match = url.match(regex);
    return match ? match[1] : null;
  };

  const handleLoadCustomVideo = () => {
    const id = extractYoutubeId(customUrl);
    if (id) {
      const newRadio = {
        id: 'custom-' + Date.now(),
        title: 'Video của bạn',
        youtubeId: id,
        thumbnail: `https://img.youtube.com/vi/${id}/0.jpg`
      };
      setActiveRadio(newRadio);
      setHistory(prev => [newRadio, ...prev.slice(0, 4)]);
      setCustomUrl('');
      showToast("Đã tải nhạc từ YouTube!");
    } else {
      showToast("Link YouTube không hợp lệ!");
    }
  };

  const progress = (((mode === 'study' ? 25 * 60 : 5 * 60) - seconds) / (mode === 'study' ? 25 * 60 : 5 * 60)) * 100;

  return (
    <div className="flex flex-col items-center h-full gap-8 py-4 animate-slide-in max-w-2xl mx-auto pb-24 overflow-y-auto px-4">
      {/* Timer Controls */}
      <div className="glass p-2 rounded-[2rem] shadow-sm border-white flex gap-1 z-10 shrink-0">
        <button 
          onClick={() => setTimerMode('study')}
          className={`px-8 py-3 rounded-[1.5rem] text-xs font-black transition-all ${mode === 'study' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-400 hover:bg-slate-50'}`}
        >
          HỌC TẬP
        </button>
        <button 
          onClick={() => setTimerMode('break')}
          className={`px-8 py-3 rounded-[1.5rem] text-xs font-black transition-all ${mode === 'break' ? 'bg-teal-500 text-white shadow-xl shadow-teal-100' : 'text-slate-400 hover:bg-slate-50'}`}
        >
          NGHỈ NGƠI
        </button>
      </div>

      {/* Main Clock Circle */}
      <div className="relative flex items-center justify-center w-72 h-72 group shrink-0 mt-4">
        <div className={`absolute inset-0 rounded-full blur-3xl opacity-20 transition-all duration-1000 ${isActive ? (mode === 'study' ? 'bg-indigo-500' : 'bg-teal-500 animate-pulse') : 'bg-slate-300'}`}></div>
        <svg className="absolute w-full h-full -rotate-90">
          <circle cx="144" cy="144" r="130" className="fill-none stroke-slate-100 stroke-[12]" />
          <circle 
            cx="144" cy="144" r="130" 
            className={`fill-none stroke-[12] transition-all duration-1000 ease-linear ${mode === 'study' ? 'stroke-indigo-600' : 'stroke-teal-500'}`}
            strokeDasharray={816}
            strokeDashoffset={816 - (816 * progress) / 100}
            strokeLinecap="round"
          />
        </svg>
        <div className="text-center z-10">
          <div className="text-6xl font-black text-slate-800 font-mono tracking-tighter mb-2 transition-all group-hover:scale-110">
            {formatTime(seconds)}
          </div>
          <div className={`text-[10px] font-black uppercase tracking-[0.3em] ${mode === 'study' ? 'text-indigo-400' : 'text-teal-400'}`}>
            {isActive ? <span className="flex items-center gap-1 justify-center"><Waves size={12} className="animate-pulse" /> Focus Flow</span> : 'Deep Work Zone'}
          </div>
        </div>
      </div>

      {/* Primary Actions */}
      <div className="flex items-center gap-6 shrink-0">
        <button 
          onClick={resetTimer}
          className="p-5 bg-white text-slate-400 rounded-3xl border border-slate-100 shadow-sm hover:text-slate-600 hover:shadow-md transition-all active:scale-90"
        >
          <RotateCcw size={28} />
        </button>

        <button 
          onClick={toggleTimer} 
          className={`px-12 py-5 rounded-[2.5rem] font-black text-white shadow-2xl transition-all active:scale-95 flex items-center gap-4 text-lg ${
            isActive ? 'bg-slate-800 shadow-slate-200' : 'bg-indigo-600 shadow-indigo-100 hover:scale-105'
          }`}
        >
          {isActive ? <><Pause size={28} fill="currentColor" /> DỪNG</> : <><Play size={28} fill="currentColor" /> BẮT ĐẦU</>}
        </button>

        <button 
          onClick={() => setShowPlayer(!showPlayer)}
          className={`p-5 rounded-3xl border transition-all active:scale-90 ${showPlayer ? 'bg-indigo-50 border-indigo-200 text-indigo-600 shadow-inner' : 'bg-white border-slate-100 text-slate-400 shadow-sm'}`}
        >
          <Music size={28} className={activeRadio ? 'animate-bounce' : ''} />
        </button>
      </div>

      {/* YouTube Music Hub */}
      {showPlayer && (
        <div className="w-full space-y-6 animate-slide-in">
          {/* Active Floating Player */}
          {activeRadio && (
            <div className="glass rounded-[2.5rem] border-white shadow-2xl overflow-hidden animate-slide-in bg-slate-900 group">
              <div className="aspect-video w-full relative">
                <iframe
                  width="100%"
                  height="100%"
                  src={`https://www.youtube.com/embed/${activeRadio.youtubeId}?autoplay=1&mute=0&controls=1`}
                  title="YouTube Player"
                  frameBorder="0"
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                ></iframe>
                <button 
                  onClick={() => setActiveRadio(null)}
                  className="absolute top-4 right-4 p-2 bg-black/60 text-white rounded-full hover:bg-rose-500 transition-all opacity-0 group-hover:opacity-100"
                >
                  <X size={16} />
                </button>
              </div>
              <div className="p-6 bg-white flex items-center justify-between border-t border-slate-50">
                  <div className="flex items-center gap-4">
                      <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600">
                          <Youtube size={24} />
                      </div>
                      <div>
                        <h4 className="font-black text-slate-800 text-sm truncate max-w-[180px]">{activeRadio.title}</h4>
                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Vibe: High Productivity</p>
                      </div>
                  </div>
                  <div className="flex gap-1 items-end h-6">
                      {[1,2,3,4,5,6].map(i => (
                        <div key={i} className="w-1 bg-indigo-500 rounded-full animate-pulse" style={{ height: `${Math.random() * 100}%`, animationDelay: `${i * 0.1}s` }}></div>
                      ))}
                  </div>
              </div>
            </div>
          )}

          {/* Custom Search & Input Area */}
          <div className="glass p-8 rounded-[3rem] border-white shadow-sm space-y-6">
            <div className="flex items-center gap-3 mb-2">
              <div className="p-2 bg-indigo-100 text-indigo-600 rounded-xl">
                <Search size={20} />
              </div>
              <h3 className="font-black text-slate-800 text-sm uppercase tracking-widest">Tự kiếm nhạc</h3>
            </div>

            <div className="flex gap-2">
              <div className="flex-1 bg-slate-50 rounded-2xl border border-slate-200 flex items-center px-4 focus-within:bg-white focus-within:border-indigo-400 transition-all group">
                <LinkIcon size={18} className="text-slate-300 group-focus-within:text-indigo-500" />
                <input 
                  value={customUrl}
                  onChange={e => setCustomUrl(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && handleLoadCustomVideo()}
                  placeholder="Dán link YouTube tại đây..."
                  className="bg-transparent border-none outline-none flex-1 py-4 px-3 text-sm font-bold text-slate-700 placeholder:text-slate-300"
                />
              </div>
              <button 
                onClick={handleLoadCustomVideo}
                disabled={!customUrl.trim()}
                className="p-4 bg-indigo-600 text-white rounded-2xl shadow-xl shadow-indigo-100 active:scale-95 disabled:opacity-50 transition-all"
              >
                <Zap size={24} fill="currentColor" />
              </button>
            </div>

            <p className="text-[10px] text-slate-400 font-bold italic text-center">Mẹo: Bạn có thể tìm bất kỳ nhạc thiền, nhạc sóng não alpha, hay podcast trên YouTube để dán vào đây.</p>
          </div>

          {/* Presets & History */}
          <div className="grid grid-cols-2 gap-6">
            <div className="space-y-4">
              <div className="flex items-center gap-2 px-2 text-slate-400">
                <Zap size={14} />
                <span className="text-[10px] font-black uppercase tracking-widest">Presets</span>
              </div>
              <div className="space-y-3">
                {PRESET_RADIOS.map(radio => (
                  <button 
                    key={radio.id}
                    onClick={() => setActiveRadio(radio)}
                    className="w-full flex items-center gap-3 p-3 glass rounded-2xl border-white hover:bg-indigo-50 transition-all group"
                  >
                    <img src={radio.thumbnail} className="w-10 h-10 rounded-xl object-cover" />
                    <span className="text-[11px] font-black text-slate-600 group-hover:text-indigo-600 truncate">{radio.title}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-4">
              <div className="flex items-center gap-2 px-2 text-slate-400">
                <History size={14} />
                <span className="text-[10px] font-black uppercase tracking-widest">Gần đây</span>
              </div>
              <div className="space-y-3">
                {history.length > 0 ? history.map(radio => (
                  <button 
                    key={radio.id}
                    onClick={() => setActiveRadio(radio)}
                    className="w-full flex items-center gap-3 p-3 glass rounded-2xl border-white hover:bg-teal-50 transition-all group"
                  >
                    <img src={radio.thumbnail} className="w-10 h-10 rounded-xl object-cover" />
                    <span className="text-[11px] font-black text-slate-600 group-hover:text-teal-600 truncate">Vừa nghe</span>
                  </button>
                )) : (
                  <div className="p-4 border border-dashed border-slate-200 rounded-2xl text-center text-[9px] text-slate-300 font-bold uppercase">Chưa có lịch sử</div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Bottom Tip (Only if player hidden) */}
      {!showPlayer && (
        <div className="glass p-6 rounded-[2.5rem] border-white shadow-sm w-full text-center flex items-center justify-between animate-slide-in shrink-0">
          <div className="flex items-center gap-4 text-left">
            <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600">
              <Award size={24} />
            </div>
            <div>
              <h4 className="font-black text-slate-800 text-sm uppercase tracking-tight">Focus Mastery</h4>
              <p className="text-[10px] text-slate-400 font-bold uppercase mt-0.5">Hoàn thành để nhận huy hiệu tuần</p>
            </div>
          </div>
          <button className="p-3 bg-slate-50 text-slate-400 rounded-2xl hover:text-indigo-600 transition-colors">
            <ChevronRight size={20} />
          </button>
        </div>
      )}
    </div>
  );
};

export default FocusZone;

import { GoogleGenAI, Type } from "@google/genai";

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const callGeminiText = async (prompt: string, systemInstruction?: string): Promise<string> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: systemInstruction || "Bạn là một trợ lý học tập thông minh, thân thiện và hài hước cho học sinh Việt Nam.",
        temperature: 0.7,
      },
    });
    return response.text || "Xin lỗi, mình đang gặp chút trục trặc trong lúc suy nghĩ.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Hệ thống AI đang bận, bạn thử lại sau nhé!";
  }
};

/* Tìm kiếm danh sách video YouTube dựa trên từ khóa */
export const searchYoutubeVideos = async (query: string): Promise<{id: string, title: string}[]> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Tìm cho tôi 4 video YouTube phổ biến nhất về chủ đề: "${query}". Trả về danh sách JSON gồm ID video và tiêu đề rút gọn.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING, description: "YouTube Video ID" },
              title: { type: Type.STRING, description: "Tên video rút gọn" }
            },
            required: ["id", "title"]
          }
        }
      }
    });

    const results = JSON.parse(response.text || "[]");
    return results;
  } catch (error) {
    console.error("Search Error:", error);
    return [];
  }
};

export const analyzeStudyImage = async (base64Image: string, prompt: string): Promise<string> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/jpeg' } },
          { text: prompt || "Hãy giải bài tập trong ảnh này và giải thích chi tiết từng bước cho mình nhé." }
        ]
      },
      config: {
        systemInstruction: "Bạn là một gia sư giỏi đa năng. Hãy phân tích hình ảnh bài tập, đưa ra đáp án chính xác và giải thích cách làm một cách dễ hiểu nhất."
