import React, { useState, useEffect } from 'react';
import { Clock, Play, Pause, RotateCcw, Award, Music, Waves, ChevronRight, X, Youtube, Search, Link as LinkIcon, History, Zap, Loader2 } from 'lucide-react';
import { searchYoutubeVideos } from '../services/geminiService';

interface FocusZoneProps {
  onExp: (amount: number) => void;
  showToast: (message: string) => void;
}

interface StudyRadio {
  id: string;
  title: string;
  youtubeId: string;
  thumbnail: string;
}

const PRESET_RADIOS: StudyRadio[] = [
  { id: 'lofi', title: 'Lofi Girl - Study Beats', youtubeId: 'jfKfPfyJRdk', thumbnail: 'https://img.youtube.com/vi/jfKfPfyJRdk/0.jpg' },
  { id: 'piano', title: 'Classical Piano Masterpieces', youtubeId: '4oZ8I9yS5-M', thumbnail: 'https://img.youtube.com/vi/4oZ8I9yS5-M/0.jpg' },
  { id: 'rain', title: 'Heavy Rain in Coffee Shop', youtubeId: 'v8v1Uv_fE8s', thumbnail: 'https://img.youtube.com/vi/v8v1Uv_fE8s/0.jpg' },
];

const FocusZone: React.FC<FocusZoneProps> = ({ onExp, showToast }) => {
  const [seconds, setSeconds] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [mode, setMode] = useState<'study' | 'break'>('study');
  const [activeRadio, setActiveRadio] = useState<StudyRadio | null>(null);
  const [showPlayer, setShowPlayer] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [searchResults, setSearchResults] = useState<StudyRadio[]>([]);
  const [history, setHistory] = useState<StudyRadio[]>([]);

  useEffect(() => {
    let interval: any = null;
    if (isActive && seconds > 0) {
      interval = setInterval(() => {
        setSeconds(s => s - 1);
      }, 1000);
    } else if (seconds === 0) {
      setIsActive(false);
      // @ts-ignore
      window.confetti({ particleCount: 150, spread: 100, origin: { y: 0.7 } });

      if (mode === 'study') {
        onExp(60);
        showToast("Tập trung xuất sắc! +60 EXP 🌟");
        setMode('break');
        setSeconds(5 * 60);
      } else {
        showToast("Thời gian nghỉ đã hết. Trở lại bàn học thôi!");
        setMode('study');
        setSeconds(25 * 60);
      }
    }
    return () => clearInterval(interval);
  }, [isActive, seconds, mode, onExp, showToast]);

  const toggleTimer = () => setIsActive(!isActive);

  const resetTimer = () => {
    setIsActive(false);
    setSeconds(mode === 'study' ? 25 * 60 : 5 * 60);
  };

  const setTimerMode = (newMode: 'study' | 'break') => {
    setIsActive(false);
    setMode(newMode);
    setSeconds(newMode === 'study' ? 25 * 60 : 5 * 60);
  };

  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const extractYoutubeId = (url: string) => {
    const regex = /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/i;
    const match = url.match(regex);
    return match ? match[1] : null;
  };

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;

    // Kiểm tra nếu là URL thì load thẳng
    const urlId = extractYoutubeId(searchQuery);
    if (urlId) {
      const directVideo = {
        id: 'direct-' + Date.now(),
        title: 'Video từ liên kết',
        youtubeId: urlId,
        thumbnail: `https://img.youtube.com/vi/${urlId}/0.jpg`
      };
      playVideo(directVideo);
      setSearchQuery('');
      return;
    }

    // Nếu không phải URL thì dùng AI tìm kiếm
    setIsSearching(true);
    const results = await searchYoutubeVideos(searchQuery);
    const mappedResults = results.map(r => ({
      id: r.id,
      title: r.title,
      youtubeId: r.id,
      thumbnail: `https://img.youtube.com/vi/${r.id}/0.jpg`
    }));
    setSearchResults(mappedResults);
    setIsSearching(false);
  };

  const playVideo = (video: StudyRadio) => {
    setActiveRadio(video);
    setHistory(prev => {
      const filtered = prev.filter(h => h.youtubeId !== video.youtubeId);
      return [video, ...filtered].slice(0, 4);
    });
    setSearchResults([]);
    setSearchQuery('');
  };

  const progress = (((mode === 'study' ? 25 * 60 : 5 * 60) - seconds) / (mode === 'study' ? 25 * 60 : 5 * 60)) * 100;

  return (
    <div className="flex flex-col items-center h-full gap-8 py-4 animate-slide-in max-w-2xl mx-auto pb-24 overflow-y-auto px-4">
      {/* Timer Controls */}
      <div className="glass p-2 rounded-[2rem] shadow-sm border-white flex gap-1 z-10 shrink-0">
        <button 
          onClick={() => setTimerMode('study')}
          className={`px-8 py-3 rounded-[1.5rem] text-xs font-black transition-all ${mode === 'study' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-400 hover:bg-slate-50'}`}
        >
          HỌC TẬP
        </button>
        <button 
          onClick={() => setTimerMode('break')}
          className={`px-8 py-3 rounded-[1.5rem] text-xs font-black transition-all ${mode === 'break' ? 'bg-teal-500 text-white shadow-xl shadow-teal-100' : 'text-slate-400 hover:bg-slate-50'}`}
        >
          NGHỈ NGƠI
        </button>
      </div>

      {/* Main Clock */}
      <div className="relative flex items-center justify-center w-72 h-72 group shrink-0 mt-4">
        <div className={`absolute inset-0 rounded-full blur-3xl opacity-20 transition-all duration-1000 ${isActive ? (mode === 'study' ? 'bg-indigo-500' : 'bg-teal-500 animate-pulse') : 'bg-slate-300'}`}></div>
        <svg className="absolute w-full h-full -rotate-90">
          <circle cx="144" cy="144" r="130" className="fill-none stroke-slate-100 stroke-[12]" />
          <circle 
            cx="144" cy="144" r="130" 
            className={`fill-none stroke-[12] transition-all duration-1000 ease-linear ${mode === 'study' ? 'stroke-indigo-600' : 'stroke-teal-500'}`}
            strokeDasharray={816}
            strokeDashoffset={816 - (816 * progress) / 100}
            strokeLinecap="round"
          />
        </svg>
        <div className="text-center z-10">
          <div className="text-6xl font-black text-slate-800 font-mono tracking-tighter mb-2 transition-all group-hover:scale-110">
            {formatTime(seconds)}
          </div>
          <div className={`text-[10px] font-black uppercase tracking-[0.3em] ${mode === 'study' ? 'text-indigo-400' : 'text-teal-400'}`}>
            {isActive ? <span className="flex items-center gap-1 justify-center"><Waves size={12} className="animate-pulse" /> Focus Flow</span> : 'Deep Work Zone'}
          </div>
        </div>
      </div>

      {/* Primary Actions */}
      <div className="flex items-center gap-6 shrink-0">
        <button 
          onClick={resetTimer}
          className="p-5 bg-white text-slate-400 rounded-3xl border border-slate-100 shadow-sm hover:text-slate-600 hover:shadow-md transition-all active:scale-90"
        >
          <RotateCcw size={28} />
        </button>

        <button 
          onClick={toggleTimer} 
          className={`px-12 py-5 rounded-[2.5rem] font-black text-white shadow-2xl transition-all active:scale-95 flex items-center gap-4 text-lg ${
            isActive ? 'bg-slate-800 shadow-slate-200' : 'bg-indigo-600 shadow-indigo-100 hover:scale-105'
          }`}
        >
          {isActive ? <><Pause size={28} fill="currentColor" /> DỪNG</> : <><Play size={28} fill="currentColor" /> BẮT ĐẦU</>}
        </button>

        <button 
          onClick={() => setShowPlayer(!showPlayer)}
          className={`p-5 rounded-3xl border transition-all active:scale-90 ${showPlayer ? 'bg-indigo-50 border-indigo-200 text-indigo-600 shadow-inner' : 'bg-white border-slate-100 text-slate-400 shadow-sm'}`}
        >
          <Music size={28} className={activeRadio ? 'animate-bounce' : ''} />
        </button>
      </div>

      {/* YouTube Search & Player Hub */}
      {showPlayer && (
        <div className="w-full space-y-6 animate-slide-in">
          {/* Active Floating Player */}
          {activeRadio && (
            <div className="glass rounded-[2.5rem] border-white shadow-2xl overflow-hidden animate-slide-in bg-slate-900 group">
              <div className="aspect-video w-full relative">
                <iframe
                  width="100%"
                  height="100%"
                  src={`https://www.youtube.com/embed/${activeRadio.youtubeId}?autoplay=1&mute=0&controls=1`}
                  title="YouTube Player"
                  frameBorder="0"
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                ></iframe>
                <button 
                  onClick={() => setActiveRadio(null)}
                  className="absolute top-4 right-4 p-2 bg-black/60 text-white rounded-full hover:bg-rose-500 transition-all opacity-0 group-hover:opacity-100"
                >
                  <X size={16} />
                </button>
              </div>
              <div className="p-6 bg-white border-t border-slate-50">
                  <h4 className="font-black text-slate-800 text-sm truncate">{activeRadio.title}</h4>
                  <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Vibe: Productivity High</p>
              </div>
            </div>
          )}

          {/* Search Box */}
          <div className="glass p-6 rounded-[2.5rem] border-white shadow-sm space-y-4">
            <div className="flex items-center justify-between mb-2">
                <div className="flex items-center gap-2">
                    <Youtube size={20} className="text-rose-500" />
                    <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Search Music</h3>
                </div>
            </div>

            <div className="flex gap-2">
              <div className="flex-1 bg-slate-50 rounded-2xl border border-slate-200 flex items-center px-4 focus-within:bg-white focus-within:border-indigo-400 transition-all group shadow-inner">
                <Search size={18} className="text-slate-300 group-focus-within:text-indigo-500" />
                <input 
                  value={searchQuery}
                  onChange={e => setSearchQuery(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && handleSearch()}
                  placeholder="Nhập tên bài hát hoặc dán link..."
                  className="bg-transparent border-none outline-none flex-1 py-4 px-3 text-sm font-bold text-slate-700 placeholder:text-slate-300"
                />
              </div>
              <button 
                onClick={handleSearch}
                disabled={!searchQuery.trim() || isSearching}
                className="p-4 bg-indigo-600 text-white rounded-2xl shadow-xl shadow-indigo-100 active:scale-95 disabled:opacity-50 transition-all"
              >
                {isSearching ? <Loader2 size={24} className="animate-spin" /> : <Zap size={24} fill="currentColor" />}
              </button>
            </div>

            {/* Search Results Display */}
            {searchResults.length > 0 && (
                <div className="grid grid-cols-1 gap-3 mt-4 animate-slide-in">
                    {searchResults.map((video) => (
                        <button 
                            key={video.id}
                            onClick={() => playVideo(video)}
