                        >
                            <img src={video.thumbnail} className="w-20 h-12 rounded-lg object-cover shadow-sm" />
                            <div className="flex-1 overflow-hidden">
                                <h5 className="font-black text-slate-700 text-[11px] truncate group-hover:text-indigo-600">{video.title}</h5>
                                <p className="text-[9px] text-slate-400 font-bold uppercase mt-0.5">Click để phát</p>
                            </div>
                        </button>
                    ))}
                </div>
            )}
          </div>

          {/* Presets & Recent */}
          <div className="grid grid-cols-2 gap-4">
             <div className="glass p-5 rounded-[2rem] border-white shadow-sm">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-3 block">Gợi ý</span>
                <div className="space-y-3">
                    {PRESET_RADIOS.map(r => (
                        <button key={r.id} onClick={() => playVideo(r)} className="w-full flex items-center gap-2 group">
                            <img src={r.thumbnail} className="w-8 h-8 rounded-lg object-cover shrink-0" />
                            <span className="text-[10px] font-black text-slate-600 truncate group-hover:text-indigo-600">{r.title}</span>
                        </button>
                    ))}
                </div>
             </div>
             <div className="glass p-5 rounded-[2rem] border-white shadow-sm">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-3 block">Vừa nghe</span>
                <div className="space-y-3">
                    {history.length > 0 ? history.map(r => (
                        <button key={r.id} onClick={() => playVideo(r)} className="w-full flex items-center gap-2 group">
                            <img src={r.thumbnail} className="w-8 h-8 rounded-lg object-cover shrink-0" />
                            <span className="text-[10px] font-black text-slate-600 truncate group-hover:text-indigo-600">Lịch sử</span>
                        </button>
                    )) : (
                        <div className="h-20 flex items-center justify-center text-[8px] text-slate-300 font-black uppercase text-center">Trống</div>
                    )}
                </div>
             </div>
          </div>
        </div>
      )}

      {!showPlayer && (
        <div className="glass p-6 rounded-[2.5rem] border-white shadow-sm w-full flex items-center justify-between animate-slide-in shrink-0">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600">
              <Award size={24} />
            </div>
            <div>
              <h4 className="font-black text-slate-800 text-sm uppercase tracking-tight">Deep Focus</h4>
              <p className="text-[10px] text-slate-400 font-bold uppercase mt-0.5">Nghe nhạc giúp tập trung 200%</p>
            </div>
          </div>
          <button className="p-3 bg-slate-50 text-slate-400 rounded-2xl hover:text-indigo-600 transition-colors">
            <ChevronRight size={20} />
          </button>
        </div>
      )}
    </div>
  );
};

