import React, { useState } from 'react';
import { 
  Wand2, BookOpen, ListChecks, CalendarDays, 
  ChevronRight, ArrowLeft, Loader2, Sparkles, 
  Copy, Check, LayoutGrid, RotateCw
} from 'lucide-react';
import { summarizeText, generateFlashcards, generateStudyPlan } from '../services/geminiService';

const StudyTools: React.FC<{ onExp: (amount: number) => void }> = ({ onExp }) => {
  const [activeTool, setActiveTool] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [result, setResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);

  const tools = [
    { 
      id: 'summary', 
      name: 'Tóm tắt thông minh', 
      desc: 'Cô đọng văn bản dài thành các ý chính cực nhanh.', 
      icon: ListChecks, 
      color: 'bg-blue-500',
      placeholder: 'Dán đoạn văn bản cần tóm tắt vào đây...'
    },
    { 
      id: 'flashcards', 
      name: 'Flashcard AI', 
      desc: 'Tự động tạo thẻ ghi nhớ từ một chủ đề học tập.', 
      icon: LayoutGrid, 
      color: 'bg-purple-500',
      placeholder: 'Nhập chủ đề (VD: Các thì trong tiếng Anh)...'
    },
    { 
      id: 'planner', 
      name: 'Lập kế hoạch 24h', 
      desc: 'AI sắp xếp lịch trình học tập tối ưu cho mục tiêu của bạn.', 
      icon: CalendarDays, 
      color: 'bg-teal-500',
      placeholder: 'Nhập mục tiêu học tập hôm nay của bạn...'
    }
  ];

  const handleRunTool = async () => {
    if (!input.trim()) return;
    setLoading(true);
    setResult(null);

    try {
      if (activeTool === 'summary') {
        const res = await summarizeText(input);
        setResult(res);
      } else if (activeTool === 'flashcards') {
        const res = await generateFlashcards(input);
        setResult(res);
      } else if (activeTool === 'planner') {
        const res = await generateStudyPlan(input);
        setResult(res);
      }
      onExp(15);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (activeTool) {
    const tool = tools.find(t => t.id === activeTool);
    return (
      <div className="animate-slide-in pb-10 max-w-2xl mx-auto w-full">
        <button 
          onClick={() => { setActiveTool(null); setResult(null); setInput(''); }}
          className="flex items-center gap-2 text-slate-400 hover:text-indigo-600 mb-6 font-black text-[10px] uppercase tracking-widest transition-colors"
        >
          <ArrowLeft size={16} /> Quay lại kho tiện ích
        </button>

        <div className="glass rounded-[2.5rem] border-white shadow-xl overflow-hidden mb-6">
          <div className="p-8 bg-slate-50/50 border-b border-slate-100 flex items-center gap-4">
            <div className={`w-12 h-12 ${tool?.color} text-white rounded-2xl flex items-center justify-center shadow-lg`}>
              {tool && <tool.icon size={24} />}
            </div>
            <div>
              <h3 className="font-black text-slate-800 text-lg">{tool?.name}</h3>
              <p className="text-xs text-slate-400 font-bold uppercase tracking-wider">{tool?.desc}</p>
            </div>
          </div>

          <div className="p-8 space-y-6">
            <textarea 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder={tool?.placeholder}
              className="w-full h-40 bg-slate-100/50 border-none rounded-3xl p-5 text-sm font-semibold text-slate-700 outline-none focus:bg-white focus:ring-2 focus:ring-indigo-100 transition-all resize-none"
            />

            <button 
              onClick={handleRunTool}
              disabled={loading || !input.trim()}
              className="w-full py-5 bg-indigo-600 text-white rounded-3xl font-black shadow-xl shadow-indigo-100 flex items-center justify-center gap-3 disabled:opacity-50 active:scale-95 transition-all"
            >
              {loading ? <Loader2 className="animate-spin" /> : <Sparkles size={20} />}
              {loading ? 'Đang phân tích...' : 'Bắt đầu xử lý'}
            </button>
          </div>
        </div>

        {result && (
          <div className="glass rounded-[2.5rem] border-white shadow-xl p-8 animate-slide-in">
            <div className="flex justify-between items-center mb-6">
              <h4 className="font-black text-indigo-600 text-[10px] uppercase tracking-[0.2em] flex items-center gap-2">
                <Wand2 size={14} /> Kết quả từ AI
              </h4>
              <button 
                onClick={() => typeof result === 'string' && copyToClipboard(result)}
                className="p-2 text-slate-300 hover:text-indigo-600 transition-colors"
              >
                {copied ? <Check size={18} className="text-green-500" /> : <Copy size={18} />}
              </button>
            </div>

            <div className="prose prose-slate max-w-none">
              {activeTool === 'flashcards' && Array.isArray(result) ? (
                <div className="grid gap-4">
                  {result.map((card, i) => (
                    <div key={i} className="p-5 bg-slate-50 border border-slate-100 rounded-3xl group hover:bg-white hover:shadow-md transition-all">
                      <div className="text-[9px] font-black text-indigo-500 uppercase mb-2">Card #{i+1}</div>
                      <div className="font-bold text-slate-800 mb-2">Q: {card.front}</div>
                      <div className="text-slate-500 text-sm border-t border-slate-100 pt-2 mt-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        A: {card.back}
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-slate-700 whitespace-pre-wrap font-medium leading-relaxed">
                  {result}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-slide-in max-w-2xl mx-auto w-full">
      <div className="text-center py-4">
        <h2 className="text-3xl font-black text-slate-800 tracking-tighter mb-2">Kho Tiện Ích AI</h2>
        <p className="text-slate-400 font-semibold text-sm">Nâng cấp hiệu suất học tập với trợ năng thông minh</p>
      </div>

      <div className="grid gap-4">
        {tools.map((tool) => (
          <button 
            key={tool.id}
            onClick={() => setActiveTool(tool.id)}
            className="glass p-6 rounded-[2.5rem] border-white shadow-sm hover:shadow-xl hover:shadow-indigo-50 transition-all flex items-center gap-6 group text-left"
          >
            <div className={`w-16 h-16 ${tool.color} text-white rounded-[1.5rem] flex items-center justify-center shadow-lg group-hover:rotate-6 transition-transform`}>
              <tool.icon size={32} />
            </div>
            <div className="flex-1">
              <h3 className="font-black text-slate-800 text-base mb-1">{tool.name}</h3>
              <p className="text-xs text-slate-400 font-semibold line-clamp-1">{tool.desc}</p>
            </div>
            <div className="w-10 h-10 bg-slate-50 rounded-full flex items-center justify-center text-slate-300 group-hover:bg-indigo-600 group-hover:text-white transition-all">
              <ChevronRight size={20} />
            </div>
          </button>
        ))}
      </div>

      <div className="glass p-8 rounded-[3rem] border-white shadow-sm flex items-center gap-6 mt-12 overflow-hidden relative group cursor-pointer hover:shadow-md transition-all">
          <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:rotate-12 transition-transform">
              <Sparkles size={100} />
          </div>
          <div className="w-14 h-14 bg-amber-50 text-amber-500 rounded-2xl flex items-center justify-center shrink-0">
              <RotateCw size={28} className="animate-spin-slow" />
          </div>
          <div>
              <h4 className="font-black text-slate-800 text-sm uppercase tracking-tight">Sắp ra mắt</h4>
              <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Hợp nhất đề thi, Phân tích biểu đồ và nhiều hơn nữa...</p>
          </div>
      </div>
    </div>
  );
};

export default StudyTools;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Home, Zap, Trophy, Send, Sparkles, Heart, MessageCircle, 
  Plus, Bot, Stars, Search, Menu, X, Flame, Share2, 
  Edit3, Layout, Calculator, User, Award, Users, Settings,
  CheckCircle2, Crown, Ghost, BookOpen, GraduationCap,
  LogOut, ArrowRight, Bell, Clock, BrainCircuit, Target, 
  ThumbsUp, Smile, MoreHorizontal, ThumbsDown, Scale,
  ChevronRight, Calendar, LayoutGrid
} from 'lucide-react';
import { UserProfile, AppTab } from './types';
import { getLevelInfo } from './constants';
import Feed from './components/Feed';
import AITutor from './components/AITutor';
import FocusZone from './components/FocusZone';
import QuizArena from './components/QuizArena';
import Leaderboard from './components/Leaderboard';
import Profile from './components/Profile';
import StudyTools from './components/StudyTools';

const App: React.FC = () => {
  const [userData, setUserData] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.FEED);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  useEffect(() => {
    const savedData = localStorage.getItem('studygram_user');
    if (savedData) {
      setUserData(JSON.parse(savedData));
    }
    setTimeout(() => setIsLoading(false), 1500); 
  }, []);

  useEffect(() => {
    if (userData) {
      localStorage.setItem('studygram_user', JSON.stringify(userData));
    }
  }, [userData]);

  const showToast = useCallback((message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  }, []);

  const handleAddExp = useCallback((amount: number) => {
    setUserData(prev => {
      if (!prev) return null;
      return { ...prev, exp: prev.exp + amount };
    });
    showToast(`+${amount} EXP!`, 'success');
  }, [showToast]);

  const handleOnboarding = (name: string) => {
    const newUser: UserProfile = {
      uid: 'user-' + Math.random().toString(36).substr(2, 9),
      name: name,
      avatar: `https://api.dicebear.com/7.x/notionists/svg?seed=${name}`,
      exp: 10,
      bio: 'Người khai phá tri thức mới 🚀',
      joinedAt: Date.now(),
      streak: 1,
      completedQuizzes: 0
    };
    setUserData(newUser);
  };

  if (isLoading) return <LoadingScreen />;
  if (!userData) return <Onboarding onComplete={handleOnboarding} />;

  return (
    <div className="min-h-screen text-slate-800 font-sans selection:bg-indigo-100 flex flex-col">
      {toast && <Toast toast={toast} />}

      <Sidebar 
        isOpen={sidebarOpen} 
        onClose={() => setSidebarOpen(false)} 
        userData={userData}
        setActiveTab={(tab) => { setActiveTab(tab); setSidebarOpen(false); }}
        activeTab={activeTab}
      />

      <Header 
        onOpenMenu={() => setSidebarOpen(true)} 
        userData={userData} 
        activeTab={activeTab}
      />

      <main className={`flex-1 flex flex-col w-full max-w-4xl mx-auto transition-all duration-500 ${activeTab === AppTab.TUTOR ? 'h-[calc(100vh-64px-80px)] overflow-hidden' : 'p-4 md:p-8 pb-32 mt-16'}`}>
        <div className="flex-1">
            {activeTab === AppTab.FEED && <Feed userData={userData} onExp={handleAddExp} />}
            {activeTab === AppTab.TUTOR && <AITutor userData={userData} onExp={handleAddExp} />}
            {activeTab === AppTab.FOCUS && <FocusZone onExp={handleAddExp} showToast={showToast} />}
            {activeTab === AppTab.TOOLS && <StudyTools onExp={handleAddExp} />}
            {activeTab === AppTab.QUIZ && <QuizArena onExp={handleAddExp} showToast={showToast} />}
            {activeTab === AppTab.RANK && <Leaderboard currentUid={userData.uid} />}
            {activeTab === AppTab.PROFILE && <Profile userData={userData} />}
        </div>
      </main>

      <BottomNav activeTab={activeTab} setActiveTab={setActiveTab} />
    </div>
  );
};

