import React, { useState, useEffect } from 'react';
import { 
  Plus, Heart, Sparkles, MessageCircle, X, ChevronDown, Send, 
  Image as ImageIcon, MapPin, Bot, BookOpen, Quote, Ghost, 
  Smile, Frown, Flame, HeartHandshake, EyeOff, LayoutGrid,
  TrendingUp, Globe
} from 'lucide-react';
import { Post, UserProfile, Comment, PostType } from '../types';
import { STUDY_CATEGORIES } from '../constants';
import { analyzeStudyPost, analyzeConfession } from '../services/geminiService';

interface FeedProps {
  userData: UserProfile;
  onExp: (amount: number) => void;
}

const Feed: React.FC<FeedProps> = ({ userData, onExp }) => {
  const [posts, setPosts] = useState<Post[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeFeedTab, setActiveFeedTab] = useState<PostType>('knowledge');

  useEffect(() => {
    const savedPosts = localStorage.getItem('studygram_posts');
    if (savedPosts) {
      setPosts(JSON.parse(savedPosts));
    } else {
      const initialPosts: Post[] = [
        {
          id: '1',
          uid: 'system',
          userName: 'Hệ thống StudyGram',
          avatar: 'https://api.dicebear.com/7.x/notionists/svg?seed=Admin',
          content: 'Chào mừng bạn đến với Góc Tâm Sự & Tri Thức! 🚀\n\nNơi bạn có thể chia sẻ kiến thức hoặc trút bỏ những áp lực học tập.',
          category: 'Chung',
          type: 'knowledge',
          createdAt: Date.now() - 3600000,
          likes: ['user-1'],
          comments: []
        }
      ];
      setPosts(initialPosts);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('studygram_posts', JSON.stringify(posts));
  }, [posts]);

  const handleCreatePost = (data: Partial<Post>) => {
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      uid: data.isAnonymous ? 'ghost' : userData.uid,
      userName: data.isAnonymous ? 'Người dùng ẩn danh' : userData.name,
      avatar: data.isAnonymous ? `https://api.dicebear.com/7.x/bottts/svg?seed=${Math.random()}` : userData.avatar,
      content: data.content || '',
      category: data.category || 'Khác',
      type: data.type || 'knowledge',
      mood: data.mood,
      isAnonymous: data.isAnonymous,
      createdAt: Date.now(),
      likes: [],
      comments: []
    };
    setPosts([newPost, ...posts]);

    // @ts-ignore
    window.confetti({ 
      particleCount: 100, 
      spread: 70, 
      origin: { y: 0.6 }, 
      colors: newPost.type === 'knowledge' ? ['#6366f1', '#a855f7'] : ['#f43f5e', '#fbbf24'] 
    });

    onExp(newPost.type === 'knowledge' ? 25 : 20);
    setIsModalOpen(false);
  };

  const toggleLike = (postId: string) => {
    setPosts(prev => prev.map(p => {
      if (p.id !== postId) return p;
      const alreadyLiked = p.likes.includes(userData.uid);
      return {
        ...p,
        likes: alreadyLiked ? p.likes.filter(id => id !== userData.uid) : [...p.likes, userData.uid]
      };
    }));
  };

  const handleAddComment = (postId: string, content: string) => {
    const newComment: Comment = {
      id: Math.random().toString(36).substr(2, 9),
      userName: userData.name,
      avatar: userData.avatar,
      content,
      createdAt: Date.now()
    };
    setPosts(prev => prev.map(p => {
      if (p.id !== postId) return p;
      return { ...p, comments: [...(p.comments || []), newComment] };
    }));
    onExp(5);
  };

  const handleAIAnalysis = async (postId: string) => {
    const post = posts.find(p => p.id === postId);
    if (!post || post.aiAnalysis) return;

    setPosts(prev => prev.map(p => p.id === postId ? { ...p, aiAnalysis: 'Đang suy nghĩ...' } : p));

    const analysis = post.type === 'knowledge' 
      ? await analyzeStudyPost(post.content)
      : await analyzeConfession(post.content);

    setPosts(prev => prev.map(p => p.id === postId ? { ...p, aiAnalysis: analysis } : p));
  };

  const filteredPosts = posts.filter(p => p.type === activeFeedTab);

  return (
    <div className="space-y-6 max-w-2xl mx-auto">
      {/* Search & Stats mini bar */}
      <div className="flex items-center justify-between px-2">
          <div className="flex items-center gap-2">
            <TrendingUp size={16} className="text-rose-500" />
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Đang hot: #OnThiHK2</span>
          </div>
          <div className="flex items-center gap-1 text-[10px] font-black text-indigo-600 uppercase">
             <Globe size={14} /> 1.2K học viên online
          </div>
      </div>

      {/* Post Creator Trigger */}
      <div 
        onClick={() => setIsModalOpen(true)} 
        className="glass p-5 rounded-[2.5rem] shadow-sm flex items-center gap-4 cursor-pointer hover:shadow-md transition-all group border-white bg-white/40"
      >
        <img src={userData.avatar} className="w-12 h-12 rounded-2xl bg-white p-0.5 border" />
        <div className="flex-1 text-slate-400 text-sm font-semibold">Hôm nay bạn muốn chia sẻ gì?</div>
        <div className="flex gap-2">
            <div className="p-3 bg-indigo-50 text-indigo-600 rounded-2xl group-hover:bg-indigo-600 group-hover:text-white transition-all shadow-sm">
              <Plus size={20} />
            </div>
        </div>
      </div>

      {/* Custom Feed Tabs */}
      <div className="flex gap-2 p-1 bg-slate-100/50 rounded-3xl w-fit mx-auto border border-white">
        <button 
          onClick={() => setActiveFeedTab('knowledge')}
          className={`flex items-center gap-2 px-6 py-2.5 rounded-2xl text-xs font-black transition-all ${activeFeedTab === 'knowledge' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-400 hover:bg-white'}`}
        >
          <BookOpen size={16} /> TRI THỨC
        </button>
        <button 
          onClick={() => setActiveFeedTab('story')}
          className={`flex items-center gap-2 px-6 py-2.5 rounded-2xl text-xs font-black transition-all ${activeFeedTab === 'story' ? 'bg-rose-500 text-white shadow-lg shadow-rose-100' : 'text-slate-400 hover:bg-white'}`}
        >
          <HeartHandshake size={16} /> TÂM SỰ
        </button>
      </div>

      {/* Feed List */}
      <div className="space-y-6">
        {filteredPosts.length > 0 ? filteredPosts.map(post => (
          <PostCard 
            key={post.id} 
            post={post} 
            currentUserId={userData.uid}
            onLike={() => toggleLike(post.id)} 
            onAnalyze={() => handleAIAnalysis(post.id)}
            onComment={(content) => handleAddComment(post.id, content)}
          />
        )) : (
          <div className="text-center py-20 opacity-30 flex flex-col items-center gap-4">
              <LayoutGrid size={48} />
              <p className="font-black text-sm uppercase tracking-widest">Chưa có bài đăng nào ở mục này</p>
          </div>
        )}
      </div>

      {isModalOpen && (
        <CreatePostModal 
          userData={userData}
          onClose={() => setIsModalOpen(false)} 
          onSubmit={handleCreatePost} 
          initialType={activeFeedTab}
        />
      )}
    </div>
  );
};

const PostCard: React.FC<{ 
  post: Post; 
  currentUserId: string;
  onLike: () => void; 
  onAnalyze: () => void;
  onComment: (content: string) => void;
}> = ({ post, currentUserId, onLike, onAnalyze, onComment }) => {
  const isLiked = post.likes.includes(currentUserId);
  const [showComments, setShowComments] = useState(false);
  const [commentInput, setCommentInput] = useState('');

  const handleSendComment = () => {
    if (!commentInput.trim()) return;
    onComment(commentInput.trim());
    setCommentInput('');
  };

  const isStory = post.type === 'story';

  return (
    <div className={`glass rounded-[2.5rem] p-7 border-white shadow-sm hover:shadow-xl transition-all duration-500 animate-slide-in group relative overflow-hidden ${isStory ? 'bg-gradient-to-br from-rose-50/50 to-amber-50/50' : 'bg-white/70'}`}>
      {/* Story Decoration */}
      {isStory && (
        <div className="absolute top-0 right-0 p-8 opacity-5 -rotate-12 group-hover:rotate-0 transition-transform">
            <Quote size={80} fill="currentColor" />
        </div>
      )}

      <div className="flex justify-between items-start mb-6">
        <div className="flex gap-4">
          <div className="relative">
            <img src={post.avatar} className={`w-12 h-12 rounded-2xl shadow-sm border ${post.isAnonymous ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-100'}`} />
            {post.isAnonymous && (
                <div className="absolute -top-1 -right-1 bg-slate-900 text-white p-1 rounded-lg">
                    <EyeOff size={10} />
                </div>
            )}
          </div>
          <div>
            <h4 className={`font-black text-sm tracking-tight ${post.isAnonymous ? 'text-slate-500 italic' : 'text-slate-800'}`}>
                {post.userName}
            </h4>
            <div className="flex items-center gap-2 mt-1">
              <span className={`text-[9px] px-2 py-0.5 rounded-full font-black uppercase tracking-widest shadow-sm ${
                isStory ? 'bg-rose-500 text-white' : 'bg-indigo-600 text-white'
              }`}>
                {post.mood ? `${post.mood}` : post.category}
