        <div className={`p-5 border rounded-3xl mb-6 text-sm italic shadow-inner relative overflow-hidden group/ai ${
            isStory ? 'bg-rose-50 border-rose-100 text-rose-900' : 'bg-indigo-50 border-indigo-100 text-indigo-900'
