            <Sparkles size={14} className="animate-pulse" /> {isStory ? 'Lời nhắn từ AI' : 'AI Insight'}
          </div>
          <p className="relative z-10">{post.aiAnalysis}</p>
          <div className="absolute top-0 right-0 p-4 opacity-5 group-hover/ai:scale-110 transition-transform">
