              onClick={handleSendComment}
              disabled={!commentInput.trim()}
              className={`w-10 h-10 flex items-center justify-center text-white rounded-xl disabled:opacity-30 transition-all active:scale-95 shadow-lg ${isStory ? 'bg-rose-500 shadow-rose-100' : 'bg-indigo-600 shadow-indigo-100'}`}
            >
              <Send size={18} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

