import { GoogleGenAI, Type } from "@google/genai";

// Ưu tiên FLASH cho tốc độ bàn thờ
const FLASH_MODEL = 'gemini-3-flash-preview';
const PRO_MODEL = 'gemini-3-pro-preview';

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

/**
 * Gọi AI với tiêu chí TỐC ĐỘ là trên hết
 */
export const callGeminiWithRetry = async (
  prompt: string, 
  systemInstruction?: string, 
  usePro = false,
  retries = 2 // Giảm retry để báo lỗi nhanh hơn nếu kẹt
): Promise<string> => {
  const ai = getAIInstance();

  // Nếu là Pro thì mới dùng Thinking, còn Flash thì bỏ qua cho nhanh
  const config = {
    systemInstruction: systemInstruction || "Bạn là một trợ lý học tập siêu tốc độ, trả lời cực ngắn, thông minh, hài hước.",
    temperature: 0.8,
    // Chỉ dùng thinkingBudget cho Pro để giải quyết vấn đề logic cực khó
    thinkingConfig: usePro ? { thinkingBudget: 2000 } : undefined 
  };

  for (let i = 0; i < retries; i++) {
    try {
      const response = await ai.models.generateContent({
        model: usePro ? PRO_MODEL : FLASH_MODEL,
        contents: prompt,
        config: config,
      });
      return response.text || "Lỗi rồi fen ơi!";
    } catch (error) {
      if (i === retries - 1) throw error;
      await new Promise(resolve => setTimeout(resolve, 500));
    }
  }
  return "AI đang bận tí, tí nữa quay lại nhé!";
};

/**
 * Tạo bài đăng AI vui nhộn hàng ngày
 */
export const generateFunAIPost = async (): Promise<{content: string, category: string, mood: string}> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: "Tạo 1 bài đăng vui nhộn về việc học tập (kiến thức thú vị hoặc meme bằng chữ). Ngôn ngữ Gen Z, hài hước, ngắn gọn.",
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            content: { type: Type.STRING },
            category: { type: Type.STRING },
            mood: { type: Type.STRING }
          },
          required: ["content", "category", "mood"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    return {
      content: "Học tập là niềm vui, không học là niềm... đau. Cố lên các fen! 🚀",
      category: "Động lực",
      mood: "🔥 Cháy hết mình"
    };
  }
};

