  };

  useEffect(() => {
    localStorage.setItem('studygram_posts', JSON.stringify(posts));
  }, [posts]);

  const handleCreatePost = async (data: Partial<Post>) => {
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      uid: data.isAnonymous ? 'ghost' : userData.uid,
      userName: data.isAnonymous ? 'Học giả ẩn danh' : userData.name,
      avatar: data.isAnonymous ? `https://api.dicebear.com/7.x/bottts/svg?seed=${Math.random()}` : userData.avatar,
      content: data.content || '',
      category: data.category || 'Khác',
      type: data.type || 'knowledge',
      mood: data.mood,
      isAnonymous: data.isAnonymous,
      createdAt: Date.now(),
      likes: [],
      comments: []
    };

    setPosts([newPost, ...posts]);
    onExp(newPost.type === 'knowledge' ? 25 : 20);
    setIsModalOpen(false);

    // Kích hoạt AI bình luận tự động - Flash phản hồi cực nhanh
    setTimeout(async () => {
      try {
        const aiCommentText = await generateSupportiveComment(newPost.content, newPost.type);
        const aiComment: Comment = {
          id: 'ai-' + Date.now(),
          userName: 'StudyBuddy AI',
          avatar: 'https://api.dicebear.com/7.x/bottts/svg?seed=Buddy',
          content: aiCommentText,
          createdAt: Date.now()
        };
        setPosts(prev => prev.map(p => p.id === newPost.id ? { ...p, comments: [...p.comments, aiComment] } : p));
      } catch (e) {}
    }, 1000);

    // @ts-ignore
    window.confetti({ particleCount: 80, spread: 60, origin: { y: 0.8 } });
  };

  const toggleLike = (postId: string) => {
    setPosts(prev => prev.map(p => {
      if (p.id !== postId) return p;
      const alreadyLiked = p.likes.includes(userData.uid);
      return {
        ...p,
        likes: alreadyLiked ? p.likes.filter(id => id !== userData.uid) : [...p.likes, userData.uid]
      };
    }));
  };

  const handleAddComment = (postId: string, content: string) => {
    const newComment: Comment = {
      id: Math.random().toString(36).substr(2, 9),
      userName: userData.name,
      avatar: userData.avatar,
      content,
      createdAt: Date.now()
    };
    setPosts(prev => prev.map(p => {
      if (p.id !== postId) return p;
      return { ...p, comments: [...(p.comments || []), newComment] };
    }));
    onExp(5);
  };

  const handleAIAnalysis = async (postId: string) => {
    const post = posts.find(p => p.id === postId);
    if (!post || post.aiAnalysis) return;

    setPosts(prev => prev.map(p => p.id === postId ? { ...p, aiAnalysis: 'Đang cảm nhận...' } : p));
    try {
      const analysis = post.type === 'knowledge' 
        ? await analyzeStudyPost(post.content)
        : await analyzeConfession(post.content);
      setPosts(prev => prev.map(p => p.id === postId ? { ...p, aiAnalysis: analysis } : p));
    } catch (e) {
      setPosts(prev => prev.map(p => p.id === postId ? { ...p, aiAnalysis: 'Hơi nghẽn tí fen ơi!' } : p));
    }
  };

  const filteredPosts = posts.filter(p => p.type === activeFeedTab);

  return (
    <div className="space-y-6 max-w-2xl mx-auto pb-10">
      {/* AI Inspiration Banner */}
      <div className="glass p-6 rounded-[2.5rem] bg-gradient-to-r from-indigo-500/10 via-purple-500/10 to-rose-500/10 border-white shadow-sm flex items-center gap-5 overflow-hidden relative">
          <div className="absolute top-0 right-0 p-4 opacity-10 animate-pulse">
              <Star size={60} fill="currentColor" />
          </div>
          <div className="w-14 h-14 bg-white/50 rounded-2xl flex items-center justify-center text-indigo-600 shadow-sm shrink-0">
              <Sparkles size={28} />
          </div>
          <div className="flex-1">
              <h5 className="text-[10px] font-black text-indigo-600 uppercase tracking-widest mb-1">Cảm hứng từ StudyGram</h5>
              <p className="text-sm font-bold text-slate-700 leading-tight italic">"{aiQuote}"</p>
          </div>
      </div>

      {/* Trending Bar */}
      <div className="overflow-x-auto whitespace-nowrap py-1 no-scrollbar flex gap-3 px-2">
        {hotTags.map(tag => (
          <div key={tag} className="inline-flex items-center gap-1.5 px-4 py-2 bg-white border border-slate-100 rounded-full text-[10px] font-black text-slate-500 shadow-sm hover:text-indigo-600 hover:bg-indigo-50 transition-all cursor-pointer">
            <Hash size={12} className="text-indigo-400" /> {tag.replace('#','')}
          </div>
        ))}
      </div>

      {/* Post Creator Trigger */}
      <div 
        onClick={() => setIsModalOpen(true)} 
        className="glass p-5 rounded-[2.5rem] shadow-sm flex items-center gap-4 cursor-pointer hover:shadow-md transition-all group border-white bg-white/40"
      >
        <img src={userData.avatar} className="w-12 h-12 rounded-2xl bg-white p-0.5 border" />
        <div className="flex-1 text-slate-400 text-sm font-semibold tracking-tight">Fen ơi, hôm nay học gì/tâm sự gì không?</div>
        <div className="p-3 bg-indigo-600 text-white rounded-2xl group-hover:scale-110 transition-all shadow-lg shadow-indigo-100">
          <Plus size={20} />
        </div>
      </div>

      {/* Custom Feed Tabs */}
      <div className="flex gap-2 p-1 bg-slate-200/40 rounded-3xl w-fit mx-auto border border-white">
        <button 
          onClick={() => setActiveFeedTab('knowledge')}
          className={`flex items-center gap-2 px-8 py-3 rounded-2xl text-xs font-black transition-all ${activeFeedTab === 'knowledge' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:bg-white'}`}
        >
          <BookOpen size={16} /> TRI THỨC
        </button>
        <button 
          onClick={() => setActiveFeedTab('story')}
          className={`flex items-center gap-2 px-8 py-3 rounded-2xl text-xs font-black transition-all ${activeFeedTab === 'story' ? 'bg-rose-500 text-white shadow-lg' : 'text-slate-500 hover:bg-white'}`}
        >
          <HeartHandshake size={16} /> TÂM SỰ
        </button>
      </div>

      {/* Feed List */}
      <div className="space-y-6">
        {filteredPosts.length > 0 ? filteredPosts.map(post => (
          <PostCard 
            key={post.id} 
            post={post} 
            currentUserId={userData.uid}
            onLike={() => toggleLike(post.id)} 
            onAnalyze={() => handleAIAnalysis(post.id)}
            onComment={(content) => handleAddComment(post.id, content)}
          />
        )) : (
          <div className="text-center py-20 opacity-20 flex flex-col items-center gap-4">
              <LayoutGrid size={48} />
              <p className="font-black text-sm uppercase tracking-widest">Không gian này đang chờ bạn...</p>
          </div>
        )}
      </div>

      {isModalOpen && (
        <CreatePostModal 
          userData={userData}
          onClose={() => setIsModalOpen(false)} 
          onSubmit={handleCreatePost} 
          initialType={activeFeedTab}
        />
      )}
    </div>
  );
};

