import { GoogleGenAI, Type } from "@google/genai";

const FLASH_MODEL = 'gemini-3-flash-preview';
const PRO_MODEL = 'gemini-3-pro-preview';

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const callGeminiWithRetry = async (
  prompt: string, 
  systemInstruction?: string, 
  usePro = false,
  retries = 2
): Promise<string> => {
  const ai = getAIInstance();
  const config = {
    systemInstruction: systemInstruction || "Bạn là trợ lý học tập Gen Z, hài hước, dùng từ lóng, trả lời ngắn gọn.",
    temperature: 0.9,
    thinkingConfig: usePro ? { thinkingBudget: 2000 } : undefined 
  };

  for (let i = 0; i < retries; i++) {
    try {
      const response = await ai.models.generateContent({
        model: usePro ? PRO_MODEL : FLASH_MODEL,
        contents: prompt,
        config: config,
      });
      return response.text || "Lỗi rồi fen!";
    } catch (error) {
      if (i === retries - 1) throw error;
      await new Promise(resolve => setTimeout(resolve, 500));
    }
  }
  return "AI đang đi uống trà sữa, tí quay lại!";
};

export const checkVibePost = async (content: string): Promise<{vibe: string, score: number, comment: string}> => {
  const ai = getAIInstance();
  const response = await ai.models.generateContent({
    model: FLASH_MODEL,
    contents: `Phân tích vibe bài đăng này: "${content}"`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          vibe: { type: Type.STRING, description: "Tên vibe hài hước, VD: Học giả hệ tâm linh" },
          score: { type: Type.NUMBER, description: "Điểm nỗ lực từ 1-100" },
          comment: { type: Type.STRING, description: "Nhận xét cực ngắn, chất" }
        },
        required: ["vibe", "score", "comment"]
      }
    }
  });
  return JSON.parse(response.text || "{}");
};

