        createdAt: Date.now(), likes: [], comments: []
      };
      setPosts(prev => [newPost, ...prev]);
      localStorage.setItem('last_ai_post_date', new Date().toDateString());
    } catch (e) {}
  };

  const handleVibeCheck = async (postId: string, content: string) => {
    if (vibeData[postId]) return;
    setVibeData(prev => ({ ...prev, [postId]: { loading: true } }));
    try {
      const res = await checkVibePost(content);
      setVibeData(prev => ({ ...prev, [postId]: { ...res, loading: false } }));
