      type: data.type || 'knowledge', mood: data.mood, createdAt: Date.now(), likes: [], comments: []
    };
    setPosts([newPost, ...posts]);
    onExp(20);
    setIsModalOpen(false);
    localStorage.setItem('studygram_posts', JSON.stringify([newPost, ...posts]));
  };

