            <button onClick={() => setActiveFeedTab('event')} className={`flex items-center gap-2 px-6 py-2.5 rounded-full text-[10px] font-black transition-all ${activeFeedTab === 'event' ? 'bg-amber-500 text-white' : 'text-slate-500'}`}><Crown size={12}/> SỰ KIỆN</button>
            <button onClick={() => setActiveFeedTab('knowledge')} className={`flex items-center gap-2 px-6 py-2.5 rounded-full text-[10px] font-black transition-all ${activeFeedTab === 'knowledge' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><BookOpen size={12}/> TRI THỨC</button>
            <button onClick={() => setActiveFeedTab('meme')} className={`flex items-center gap-2 px-6 py-2.5 rounded-full text-[10px] font-black transition-all ${activeFeedTab === 'meme' ? 'bg-rose-500 text-white' : 'text-slate-500'}`}><Smile size={12}/> MEME</button>
