              <Hash size={12} /> {filterTag.toUpperCase()}
              <button onClick={() => setFilterTag(null)} className="hover:rotate-90 transition-transform"><X size={14}/></button>
            </span>
          </div>
        )}
      </div>

      {/* Post List */}
      <div className="space-y-6">
        {filteredPosts.length > 0 ? (
          filteredPosts.map(post => (
            <PostCard 
              key={post.id} 
              post={post} 
              currentUserId={userData.uid} 
              vibe={vibeData[post.id]} 
              onVibeCheck={() => handleVibeCheck(post.id, post.content, post.imageUrl)}
              onTagClick={(tag) => setFilterTag(tag)}
            />
          ))
        ) : (
          <div className="text-center py-20 bg-white/40 glass rounded-[3rem] border-white">
            <Search className="mx-auto text-slate-200 mb-4" size={48} />
