            >
              ✨ Toast me!
            </button>
          </div>
        )}
      </div>

      {/* Account Info */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-xl mb-10">
         <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 px-2">Thông tin tài khoản</h4>
         <div className="space-y-4">
            <div className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl">
               <div className="flex items-center gap-3">
                  <div className="p-2 bg-white rounded-xl text-slate-400"><Lock size={18}/></div>
                  <span className="text-sm font-bold text-slate-600">Phương thức</span>
               </div>
               <span className="text-xs font-black text-indigo-600 uppercase tracking-widest bg-white px-3 py-1 rounded-full border">{userData.loginMethod}</span>
            </div>
            <div className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl">
               <div className="flex items-center gap-3">
                  <div className="p-2 bg-white rounded-xl text-slate-400"><Award size={18}/></div>
                  <span className="text-sm font-bold text-slate-600">ID Người dùng</span>
               </div>
               <span className="text-xs font-mono text-slate-400">{userData.uid}</span>
            </div>
         </div>
      </div>

      <button className="w-full py-6 bg-white border-2 border-slate-100 rounded-[2.5rem] font-black text-slate-800 shadow-xl flex items-center justify-center gap-4 hover:bg-slate-50 transition-all active:scale-95 group">
        <Share2 size={28} className="group-hover:rotate-12 transition-transform"/> CHIA SẺ VỚI ĐỒNG MÔN
      </button>

      {/* Admin Verification Modal */}
