      { uid: 's4', name: "Học Giả Ẩn Danh 👤", exp: 1200, avatar: "https://api.dicebear.com/7.x/notionists/svg?seed=Anon", rank: 4, streak: 3, isVerified: false },
      { uid: 's5', name: "Văn Chương Art 🖋️", exp: 950, avatar: "https://api.dicebear.com/7.x/notionists/svg?seed=Art", rank: 5, streak: 1, isVerified: false },
    ];
    setStudents(defaultStudents);
  }, []);

  useEffect(() => {
    const fetchTip = async () => {
      if (students.length > 0) {
        try {
          const tip = await getChampionTip(students[0].name);
          setChampionQuote(tip);
        } catch (e) {
          setChampionQuote("Học đi ngại gì, tri thức là sức mạnh! 🚀");
