      }
    };
    fetchTip();
  }, [students]);

  const handleAdminAction = (uid: string, action: 'verify' | 'promote' | 'note') => {
    if (!userData.isAdmin) return;

    setStudents(prev => prev.map(s => {
      if (s.uid === uid) {
        if (action === 'verify') return { ...s, isVerified: !s.isVerified };
