            <div className="text-lg font-black text-slate-700 mb-4">{userData.studyGoal || "Chưa có mục tiêu cụ thể"}</div>
            <div className="w-full h-3 bg-slate-200 rounded-full overflow-hidden mb-2">
                <div className="h-full bg-indigo-600 transition-all duration-1000" style={{ width: `${Math.min(userData.exp / 10, 100)}%` }}></div>
            </div>
            <div className="flex justify-between text-[10px] font-black text-slate-400 uppercase tracking-widest">
                <span>Khởi đầu</span>
                <span>{Math.floor(Math.min(userData.exp / 10, 100))}% Hoàn thành</span>
            </div>
        </div>
      </div>

      {/* AI Career Path Widget */}
      <div className="glass p-8 rounded-[3.5rem] border-white shadow-xl mb-10 bg-gradient-to-br from-indigo-500/10 to-purple-500/10 relative overflow-hidden group">
