export default Profile;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, Heart, Sparkles, MessageCircle, X, Send, 
  Bot, BookOpen, Hash, Zap, Star, Smile,
  Image as ImageIcon, Youtube, Pin, Crown, ShieldCheck,
  Calendar, Filter, Search, RefreshCw, MessageSquare
} from 'lucide-react';
import { Post, UserProfile, PostType, Comment } from '../types';
import { STUDY_CATEGORIES } from '../constants';
import { checkVibePost, suggestHashtags } from '../services/geminiService';

interface FeedProps {
  userData: UserProfile;
  onExp: (amount: number) => void;
}

const Feed: React.FC<FeedProps> = ({ userData, onExp }) => {
  const [posts, setPosts] = useState<Post[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeFeedTab, setActiveFeedTab] = useState<PostType | 'all'>('all');
  const [vibeData, setVibeData] = useState<Record<string, any>>({});
  const [filterTag, setFilterTag] = useState<string | null>(null);

  useEffect(() => {
    const savedPosts = localStorage.getItem('studygram_posts');
    if (savedPosts) {
      setPosts(JSON.parse(savedPosts));
    } else {
      setPosts([{
        id: 'sys-1', uid: 'system', userName: 'StudyGram Admin 👑', avatar: 'https://api.dicebear.com/7.x/notionists/svg?seed=Angel',
        content: 'Chào mừng các fen! Tính năng BÌNH LUẬN đã quay trở lại xịn xò hơn xưa nhé! Thử phân tích Vibe bài này xem nào. 🔥',
        category: 'Thông báo', type: 'event', createdAt: Date.now(), likes: [], 
        comments: [
          { id: 'c1', userName: 'Học giả A', avatar: 'https://api.dicebear.com/7.x/notionists/svg?seed=A', content: 'Xịn quá Admin ơi! 😍', createdAt: Date.now() }
        ],
        hashtags: ['v4', 'update', 'community'], isPinned: true
      }]);
    }
  }, []);

  const savePosts = (updatedPosts: Post[]) => {
    setPosts(updatedPosts);
    localStorage.setItem('studygram_posts', JSON.stringify(updatedPosts));
  };

  const handleVibeCheck = async (postId: string, content: string, imageUrl?: string) => {
    if (vibeData[postId]) return;
    setVibeData(prev => ({ ...prev, [postId]: { loading: true } }));
    try {
      const res = await checkVibePost(content, imageUrl);
      setVibeData(prev => ({ ...prev, [postId]: { ...res, loading: false } }));
      onExp(10);
      // @ts-ignore
      window.confetti({ particleCount: 30, spread: 30, origin: { y: 0.8 }, colors: ['#6366F1', '#EC4899'] });
    } catch (e) {
      setVibeData(prev => ({ ...prev, [postId]: null }));
    }
  };

  const handleCreatePost = (data: Partial<Post>) => {
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      uid: userData.uid,
      userName: userData.isAdmin ? `${userData.name} 👑` : userData.name,
      avatar: userData.avatar,
      content: data.content || '', 
      category: data.category || 'Khác',
      type: data.type || 'knowledge', 
      createdAt: Date.now(), 
      likes: [], 
      comments: [],
      imageUrl: data.imageUrl,
      videoUrl: data.videoUrl,
      hashtags: data.hashtags || [],
      isPinned: data.type === 'event' && userData.isAdmin
    };
    savePosts([newPost, ...posts]);
    onExp(data.type === 'event' ? 50 : 20);
    setIsModalOpen(false);
  };

  const handleAddComment = (postId: string, content: string) => {
    const updated = posts.map(p => {
      if (p.id === postId) {
        const newComment: Comment = {
          id: Math.random().toString(36).substr(2, 9),
          userName: userData.name,
          avatar: userData.avatar,
          content,
          createdAt: Date.now()
        };
        return { ...p, comments: [...(p.comments || []), newComment] };
      }
      return p;
    });
    savePosts(updated);
    onExp(5);
  };

  const filteredPosts = posts
    .filter(p => (activeFeedTab === 'all' || p.type === activeFeedTab))
    .filter(p => (!filterTag || p.hashtags?.includes(filterTag)))
    .sort((a, b) => (b.isPinned ? 1 : 0) - (a.isPinned ? 1 : 0));

  return (
    <div className="space-y-6 max-w-2xl mx-auto pb-24">
      {/* Search & Statistics Bar */}
      <div className="flex gap-4 mb-2">
        <div className="flex-1 glass px-6 py-4 rounded-[2rem] flex items-center gap-3 border-white/50 shadow-sm">
           <Search size={20} className="text-slate-400" />
           <input placeholder="Tìm chủ đề..." className="bg-transparent border-none outline-none text-sm font-bold w-full" />
        </div>
        <div className="glass px-6 py-4 rounded-[2rem] border-white/50 shadow-sm flex items-center gap-2">
           <Users size={20} className="text-indigo-500" />
           <span className="text-sm font-black text-slate-700">12.4K</span>
        </div>
      </div>

      {/* Create Section */}
      <div 
        onClick={() => setIsModalOpen(true)} 
        className="glass p-6 rounded-[2.5rem] shadow-xl flex items-center gap-4 cursor-pointer hover:scale-[1.01] active:scale-95 transition-all border-white bg-white/40 group overflow-hidden relative"
      >
        <img 
          src={userData.avatar} 
          className={`w-14 h-14 rounded-2xl bg-white border-2 shadow-sm ${userData.isAdmin ? 'border-amber-400' : 'border-indigo-100'} group-hover:rotate-6 transition-transform`} 
        />
        <div className="flex-1 text-slate-400 font-bold">
           Hôm nay bạn học được gì mới?
        </div>
        <div className="p-4 bg-indigo-600 shadow-indigo-200 text-white rounded-2xl shadow-lg"><Plus size={24} /></div>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 p-1 bg-slate-200/50 rounded-full w-fit mx-auto border border-white overflow-x-auto no-scrollbar max-w-full">
        <button onClick={() => setActiveFeedTab('all')} className={`flex items-center gap-2 px-6 py-2.5 rounded-full text-[10px] font-black transition-all ${activeFeedTab === 'all' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-800'}`}>TẤT CẢ</button>
        <button onClick={() => setActiveFeedTab('event')} className={`flex items-center gap-2 px-6 py-2.5 rounded-full text-[10px] font-black transition-all ${activeFeedTab === 'event' ? 'bg-amber-500 text-white shadow-lg' : 'text-slate-500 hover:text-slate-800'}`}><Crown size={14}/> SỰ KIỆN</button>
        <button onClick={() => setActiveFeedTab('knowledge')} className={`flex items-center gap-2 px-6 py-2.5 rounded-full text-[10px] font-black transition-all ${activeFeedTab === 'knowledge' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-800'}`}><BookOpen size={14}/> TRI THỨC</button>
        <button onClick={() => setActiveFeedTab('meme')} className={`flex items-center gap-2 px-6 py-2.5 rounded-full text-[10px] font-black transition-all ${activeFeedTab === 'meme' ? 'bg-rose-500 text-white shadow-lg' : 'text-slate-500 hover:text-slate-800'}`}><Smile size={14}/> MEME</button>
      </div>

      {/* Post List */}
      <div className="space-y-6">
        {filteredPosts.map(post => (
          <PostCard 
            key={post.id} 
            post={post} 
            currentUserId={userData.uid} 
            vibe={vibeData[post.id]} 
            onVibeCheck={() => handleVibeCheck(post.id, post.content, post.imageUrl)}
            onTagClick={(tag) => setFilterTag(tag)}
            onAddComment={(content) => handleAddComment(post.id, content)}
          />
        ))}
      </div>

      {isModalOpen && (
        <CreatePostModal 
          userData={userData} 
          onClose={() => setIsModalOpen(false)} 
          onSubmit={handleCreatePost} 
          initialType={activeFeedTab === 'all' ? 'knowledge' : activeFeedTab as PostType} 
        />
      )}
    </div>
  );
};

const PostCard: React.FC<{ 
