          {vibe.loading ? (
             <div className="flex items-center gap-3 font-black text-xs text-slate-400 justify-center py-2"><RefreshCw className="animate-spin" size={20}/> Phân tích vibe...</div>
          ) : (
            <div className="space-y-2">
              <div className="flex justify-between items-center mb-1">
                <span className="text-[9px] font-black uppercase tracking-[0.2em] opacity-80">AI Insight</span>
                <span className="text-xl font-black italic gold-text">Score: {vibe.score}/100</span>
              </div>
              <p className="text-xs font-bold opacity-90 leading-relaxed italic">"{vibe.comment}"</p>
            </div>
          )}
        </div>
