interface FeedProps {
  userData: UserProfile;
  onExp: (amount: number) => void;
}

const Feed: React.FC<FeedProps> = ({ userData, onExp }) => {
  const [posts, setPosts] = useState<Post[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeFeedTab, setActiveFeedTab] = useState<PostType | 'all'>('all');
  const [vibeData, setVibeData] = useState<Record<string, any>>({});
  const [filterTag, setFilterTag] = useState<string | null>(null);

  useEffect(() => {
    const savedPosts = localStorage.getItem('studygram_posts');
    if (savedPosts) {
      setPosts(JSON.parse(savedPosts));
    } else {
      setPosts([{
        id: 'sys-1', uid: 'system', userName: 'StudyGram Admin 👑', avatar: 'https://api.dicebear.com/7.x/notionists/svg?seed=Angel',
        content: 'Chào mừng các fen! Hệ thống Diễn đàn V4 đã sẵn sàng. Thử tính năng Mood và Reaction mới nhé! 🔥',
        category: 'Thông báo', type: 'event', mood: '🔥', createdAt: Date.now(), likes: [], 
        comments: [
          { id: 'c1', userName: 'Học giả A', avatar: 'https://api.dicebear.com/7.x/notionists/svg?seed=A', content: 'Cái Mood đỉnh quá Admin ơi! 😍', createdAt: Date.now(), isAuthor: false }
        ],
        hashtags: ['v4', 'mood', 'community'], isPinned: true
      }]);
    }
  }, []);

  const savePosts = (updatedPosts: Post[]) => {
    setPosts(updatedPosts);
    localStorage.setItem('studygram_posts', JSON.stringify(updatedPosts));
  };

  const handleCreatePost = (data: Partial<Post>) => {
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      uid: userData.uid,
      userName: userData.isAdmin ? `${userData.name} 👑` : userData.name,
      avatar: userData.avatar,
      content: data.content || '', 
      category: data.category || 'Khác',
      type: data.type || 'knowledge', 
      mood: data.mood || '📚',
      createdAt: Date.now(), 
      likes: [], 
      comments: [],
      imageUrl: data.imageUrl,
      hashtags: data.hashtags || [],
      isPinned: data.type === 'event' && userData.isAdmin
    };
    savePosts([newPost, ...posts]);
    onExp(data.type === 'event' ? 50 : 20);
    setIsModalOpen(false);
  };

  const handleAddComment = (postId: string, content: string) => {
    const updated = posts.map(p => {
      if (p.id === postId) {
        const newComment: Comment = {
          id: Math.random().toString(36).substr(2, 9),
          userName: userData.name,
          avatar: userData.avatar,
          content,
          createdAt: Date.now(),
          isAuthor: userData.uid === p.uid
        };
        return { ...p, comments: [...(p.comments || []), newComment] };
      }
      return p;
    });
    savePosts(updated);
    onExp(5);
  };

  const handleLikePost = (postId: string) => {
    const updated = posts.map(p => {
      if (p.id === postId) {
        const hasLiked = p.likes.includes(userData.uid);
        const newLikes = hasLiked ? p.likes.filter(id => id !== userData.uid) : [...p.likes, userData.uid];
        return { ...p, likes: newLikes };
      }
      return p;
    });
    savePosts(updated);
  };

  return (
    <div className="space-y-6 max-w-2xl mx-auto pb-24">
      {/* Feed Filter & Tools */}
      <div className="flex gap-4">
        <div className="flex-1 glass px-6 py-4 rounded-[2rem] flex items-center gap-3 border-white/50 shadow-sm">
           <Search size={20} className="text-slate-400" />
           <input placeholder="Tìm kiến thức..." className="bg-transparent border-none outline-none text-sm font-bold w-full" />
        </div>
      </div>

      {/* Quick Create Entry */}
      <div 
        onClick={() => setIsModalOpen(true)} 
        className="glass p-8 rounded-[3rem] shadow-2xl flex items-center gap-6 cursor-pointer hover:scale-[1.02] active:scale-95 transition-all border-white bg-white/40 group relative overflow-hidden"
      >
        <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-20 transition-opacity"><Zap size={100}/></div>
        <img 
          src={userData.avatar} 
          className={`w-16 h-16 rounded-[1.5rem] bg-white border-2 shadow-xl ${userData.isAdmin ? 'border-amber-400' : 'border-indigo-100'} group-hover:rotate-6 transition-transform`} 
        />
        <div className="flex-1">
           <div className="text-slate-400 font-black text-lg">Lan tỏa tri thức đi fen...</div>
           <div className="flex gap-2 mt-2">
              <span className="px-3 py-1 bg-indigo-50 text-indigo-500 rounded-full text-[9px] font-black uppercase tracking-widest">📚 Bài học</span>
              <span className="px-3 py-1 bg-rose-50 text-rose-500 rounded-full text-[9px] font-black uppercase tracking-widest">🎭 Meme</span>
           </div>
        </div>
        <div className="w-14 h-14 bg-indigo-600 shadow-indigo-200 text-white rounded-2xl shadow-xl flex items-center justify-center animate-bounce-slow"><Plus size={32} strokeWidth={3} /></div>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 p-1.5 bg-slate-200/40 backdrop-blur-md rounded-full w-fit mx-auto border border-white">
        {['all', 'knowledge', 'meme', 'event'].map((tab) => (
          <button 
            key={tab}
            onClick={() => setActiveFeedTab(tab as any)} 
            className={`px-8 py-3 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${activeFeedTab === tab ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:text-slate-800'}`}
          >
            {tab === 'all' ? 'Tất cả' : tab === 'knowledge' ? 'Tri thức' : tab === 'meme' ? 'Meme' : 'Sự kiện'}
          </button>
        ))}
      </div>

      {/* Feed Content */}
      <div className="space-y-10">
        {posts
          .filter(p => activeFeedTab === 'all' || p.type === activeFeedTab)
          .sort((a, b) => b.createdAt - a.createdAt)
          .map(post => (
            <PostCard 
              key={post.id} 
              post={post} 
              userData={userData}
              onLike={() => handleLikePost(post.id)}
              onAddComment={(content) => handleAddComment(post.id, content)}
            />
          ))}
      </div>

      {isModalOpen && (
        <CreatePostModal 
          userData={userData} 
          onClose={() => setIsModalOpen(false)} 
          onSubmit={handleCreatePost} 
        />
      )}
    </div>
  );
};

