            <Heart size={24} fill={hasLiked ? 'currentColor' : 'none'} />
          </div>
          {post.likes.length}
        </button>
        <button 
          onClick={() => setShowComments(!showComments)}
          className={`flex items-center gap-3 text-sm font-black transition-all ${showComments ? 'text-indigo-600' : 'text-slate-400 hover:text-indigo-600'}`}
        >
          <div className={`p-3 rounded-2xl ${showComments ? 'bg-indigo-50' : 'bg-slate-50'}`}>
