    { icon: <BookOpen size={16}/>, text: 'Tóm tắt văn bản', prompt: 'Tóm tắt ngắn gọn đoạn văn này cho mình:' },
    { icon: <Globe size={16}/>, text: 'Dịch tiếng Anh', prompt: 'Dịch đoạn này sang tiếng Anh một cách tự nhiên:' }
  ];

  useEffect(() => {
    const savedChat = localStorage.getItem('studygram_chat');
    if (savedChat) {
      setMessages(JSON.parse(savedChat));
    } else {
      setMessages([
        { 
          role: 'ai', 
          text: `Chào ${userData.name}! Mình là Gia Sư AI Perfect. 🎓\n\nBạn cần mình giúp gì hôm nay? Đừng quên mình có thể nhìn ảnh để giải bài tập nhé!`,
          timestamp: Date.now()
        }
      ]);
    }
  }, [userData.name]);

  useEffect(() => {
    localStorage.setItem('studygram_chat', JSON.stringify(messages));
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  const handleSend = async (customText?: string) => {
    const textToSend = customText || input;
    if ((!textToSend.trim() && !selectedImage) || isTyping) return;

    const userText = textToSend.trim();
    const imageToProcess = selectedImage;

    setInput('');
    setSelectedImage(null);

    const userMsg: Message = { 
      role: 'user', 
      text: imageToProcess ? `[Gửi ảnh bài tập] ${userText}` : userText, 
      timestamp: Date.now() 
    };

    setMessages(prev => [...prev, userMsg]);
    setIsTyping(true);

    let replyText = "";
    try {
      if (imageToProcess) {
        replyText = await analyzeStudyImage(imageToProcess, userText || "Phân tích và giải bài tập trong ảnh này.");
      } else {
        replyText = await getTutorResponse(userText);
      }
    } catch (e) {
      replyText = "Hệ thống AI đang quá tải, fen chờ xíu rồi hỏi lại nhé! 😴";
    }

    const aiMsg: Message = { role: 'ai', text: replyText, timestamp: Date.now() };
    setMessages(prev => [...prev, aiMsg]);
    setIsTyping(false);
    onExp(10); 
  };

  return (
    <div className="flex flex-col h-full bg-[#F4F7FF]/30">
      {/* Header chat */}
      <div className="bg-white/80 backdrop-blur-xl p-5 border-b flex items-center justify-between shadow-sm z-10 sticky top-0">
        <div className="flex items-center gap-5">
          <div className="relative group">
              <div className="absolute -inset-1 bg-indigo-500 rounded-[1.5rem] blur opacity-20 group-hover:opacity-40 transition duration-1000"></div>
              <div className="relative w-14 h-14 bg-indigo-600 rounded-[1.5rem] flex items-center justify-center text-white shadow-2xl animate-float">
                <Bot size={32} strokeWidth={2.5} />
              </div>
              <div className="absolute -bottom-1 -right-1 w-5 h-5 bg-green-500 border-4 border-white rounded-full"></div>
          </div>
          <div>
            <h3 className="font-black text-lg text-slate-800 tracking-tighter">AI Tutor Perfect</h3>
            <div className="flex items-center gap-2 mt-0.5">
               <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
               <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Đang trực tuyến</span>
            </div>
          </div>
        </div>
        <button 
          onClick={() => { if(window.confirm('Xóa chat?')) setMessages([]); }}
          className="p-4 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-all"
        >
          <Trash2 size={24} />
        </button>
      </div>

      {/* Message Area */}
      <div className="flex-1 overflow-y-auto p-8 space-y-10 no-scrollbar">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-6 rounded-[2.5rem] text-sm leading-relaxed shadow-xl animate-slide-in font-bold tracking-tight ${
              m.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-tr-none shadow-indigo-100' 
                : 'bg-white border border-slate-100 text-slate-700 rounded-tl-none border-b-4 border-slate-200'
            }`}>
              {m.text.split('\n').map((line, idx) => (
                <p key={idx} className={idx > 0 ? 'mt-2' : ''}>{line}</p>
              ))}
              <div className={`mt-3 text-[9px] uppercase tracking-widest opacity-40 ${m.role === 'user' ? 'text-white' : 'text-slate-400'}`}>
                 {new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </div>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-start">
            <div className="bg-white border-2 border-slate-100 p-6 rounded-[2.5rem] rounded-tl-none shadow-xl flex gap-2">
              <div className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-bounce"></div>
              <div className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:0.2s]"></div>
              <div className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:0.4s]"></div>
            </div>
          </div>
        )}
        <div ref={chatEndRef} />
      </div>

      {/* Input & Quick Tools Area */}
      <div className="p-6 bg-white/80 backdrop-blur-xl border-t border-slate-100 safe-area-bottom">
        <div className="flex gap-2 mb-4 overflow-x-auto no-scrollbar pb-2">
           {quickPrompts.map((qp, idx) => (
             <button 
               key={idx}
               onClick={() => setInput(qp.prompt)}
               className="flex items-center gap-2 px-4 py-2.5 bg-indigo-50 text-indigo-600 rounded-2xl text-[10px] font-black uppercase tracking-widest whitespace-nowrap hover:bg-indigo-600 hover:text-white transition-all shadow-sm active:scale-95"
             >
                {qp.icon} {qp.text}
             </button>
           ))}
        </div>

        {selectedImage && (
            <div className="mb-4 relative inline-block animate-slide-in">
                <img src={selectedImage} className="w-32 h-32 object-cover rounded-[2rem] border-4 border-white shadow-2xl" />
                <button 
                    onClick={() => setSelectedImage(null)}
                    className="absolute -top-3 -right-3 bg-rose-500 text-white p-2 rounded-xl shadow-xl hover:rotate-90 transition-transform"
                >
                    <X size={16} strokeWidth={3} />
                </button>
            </div>
        )}

        <div className="flex items-center gap-3 bg-slate-50 p-3 rounded-[2.5rem] border-2 border-slate-100 focus-within:border-indigo-400 focus-within:bg-white transition-all shadow-inner">
          <input 
            type="file" 
            accept="image/*" 
            ref={fileInputRef} 
            onChange={(e) => {
               const file = e.target.files?.[0];
               if(file) {
                 const reader = new FileReader();
                 reader.onloadend = () => setSelectedImage(reader.result as string);
                 reader.readAsDataURL(file);
               }
            }} 
            className="hidden" 
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="p-4 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-[1.5rem] transition-all active:scale-90"
          >
            <Camera size={24} strokeWidth={2.5} />
          </button>
          <input 
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSend()}
            placeholder={selectedImage ? "Thêm lời nhắn cho đề bài..." : "Hỏi bài tập hoặc dán link đề..."}
            className="flex-1 bg-transparent px-2 py-3 outline-none text-base font-bold placeholder:text-slate-300"
          />
          <button 
            onClick={() => handleSend()} 
            disabled={(!input.trim() && !selectedImage) || isTyping}
            className={`w-14 h-14 flex items-center justify-center rounded-[1.8rem] transition-all active:scale-95 shadow-2xl ${
              (input.trim() || selectedImage) && !isTyping 
                ? 'bg-indigo-600 text-white shadow-indigo-200' 
                : 'bg-slate-100 text-slate-300 shadow-none'
            }`}
          >
            <Send size={24} strokeWidth={3} />
          </button>
        </div>
      </div>
    </div>
  );
};

