         <p className="text-slate-400 font-bold uppercase tracking-widest text-[11px]">Nơi những học giả vĩ đại nhất được khắc tên</p>
      </div>

      {/* Champion Spotlight - The Divine Seat */}
      {studentOfWeek && (
        <div className="relative glass p-12 rounded-[4.5rem] border-white shadow-2xl bg-gradient-to-br from-[#1a1c2c] via-[#4a192c] to-[#121212] text-white overflow-hidden group border-2">
            <div className="absolute top-0 right-0 p-12 opacity-10 rotate-12 group-hover:rotate-0 transition-transform duration-1000">
              <Trophy size={300} />
