import React, { useState, useEffect } from 'react';
import { 
  Crown, Medal, Award, Flame, Zap, ArrowUp, Sparkles, Trophy, User, 
  Share2, Bot, TrendingUp, ShieldCheck, Star, Edit3, CheckCircle2,
  MoreVertical, Info, Gavel, Globe, Heart, Ghost
} from 'lucide-react';
import { getChampionTip } from '../services/geminiService';
import { UserProfile } from '../types';

interface LeaderboardProps {
  currentUid: string;
  userData: UserProfile;
}

const Leaderboard: React.FC<LeaderboardProps> = ({ currentUid, userData }) => {
  const [activeRange, setActiveRange] = useState<'weekly' | 'all-time'>('weekly');
  const [championQuote, setChampionQuote] = useState("Vị thế này chỉ dành cho những người không bao giờ bỏ cuộc! 🌌");
  const [students, setStudents] = useState<any[]>([]);

  useEffect(() => {
    // Lấy dữ liệu thực từ localStorage (nếu có người dùng khác đã từng đăng nhập trên máy này)
    // Trong môi trường demo, chúng ta sẽ ưu tiên hiển thị user hiện tại và các user thực tế
    const savedPosts = localStorage.getItem('studygram_posts');
    const posts = savedPosts ? JSON.parse(savedPosts) : [];

    // Thu thập danh sách user thực từ các bài post
    const uniqueUsersMap = new Map();
    // Luôn thêm user hiện tại
    uniqueUsersMap.set(userData.uid, {
      uid: userData.uid,
      name: userData.name,
      avatar: userData.avatar,
      exp: userData.exp,
      streak: userData.streak,
      isVerified: userData.isVerified,
      isStudentOfWeek: userData.exp > 500 // Demo logic: ai trên 500 EXP là Student of week
    });

    // Thêm các user khác từ bài post để bảng xếp hạng sinh động hơn (nhưng vẫn là user thực đã tương tác)
    posts.forEach((p: any) => {
      if (!uniqueUsersMap.has(p.uid)) {
        uniqueUsersMap.set(p.uid, {
          uid: p.uid,
          name: p.userName,
          avatar: p.avatar,
          exp: Math.floor(Math.random() * 200) + 50, // Mock EXP cho các user khác để demo
          streak: 1,
          isVerified: false,
          isStudentOfWeek: false
        });
      }
    });

    const sortedStudents = Array.from(uniqueUsersMap.values())
      .sort((a, b) => b.exp - a.exp)
      .map((s, idx) => ({ ...s, rank: idx + 1 }));

    setStudents(sortedStudents);
  }, [userData]);

  useEffect(() => {
    const fetchTip = async () => {
      if (students.length > 0 && students[0].uid === userData.uid) {
        try {
          const tip = await getChampionTip(userData.name);
          setChampionQuote(tip);
        } catch (e) {
          setChampionQuote("Ánh sáng của tri thức sẽ dẫn lối bạn tới những vì sao! ✨");
        }
      }
    };
    fetchTip();
  }, [students, userData.name]);

  const studentOfWeek = students.find(s => s.isStudentOfWeek) || students[0];

  return (
    <div className="space-y-12 animate-slide-up pb-32 max-w-2xl mx-auto w-full">
      {/* Pantheon Header */}
      <div className="text-center space-y-4">
         <div className="inline-flex items-center gap-3 px-6 py-2 bg-indigo-600 text-white rounded-full text-[10px] font-black uppercase tracking-[0.4em] shadow-xl shadow-indigo-200">
            <Globe size={14} className="animate-spin-slow" /> Không giới hạn tri thức
         </div>
         <h2 className="text-5xl font-black text-slate-800 tracking-tighter leading-none">BẢNG PHONG THẦN</h2>
         <p className="text-slate-400 font-bold uppercase tracking-widest text-[11px]">Nơi những học giả vĩ đại nhất được khắc tên</p>
      </div>

      {/* Champion Spotlight - The Divine Seat */}
      {studentOfWeek && (
        <div className="relative glass p-12 rounded-[4.5rem] border-white shadow-2xl bg-gradient-to-br from-[#1a1c2c] via-[#4a192c] to-[#121212] text-white overflow-hidden group border-2">
            <div className="absolute top-0 right-0 p-12 opacity-10 rotate-12 group-hover:rotate-0 transition-transform duration-1000">
              <Trophy size={300} />
            </div>
            {/* Animated background stars effect */}
            <div className="absolute inset-0 opacity-30">
               <div className="absolute top-1/4 left-1/4 w-1 h-1 bg-white rounded-full animate-ping"></div>
               <div className="absolute top-1/2 left-3/4 w-1 h-1 bg-white rounded-full animate-ping [animation-delay:1s]"></div>
            </div>

            <div className="relative z-10 flex flex-col items-center text-center">
                <div className="mb-6 bg-amber-500/20 backdrop-blur-xl px-8 py-3 rounded-full text-[11px] font-black uppercase tracking-[0.3em] flex items-center gap-3 border border-amber-500/30 text-amber-400">
                    <Crown size={16} fill="currentColor" className="animate-bounce"/> THE DIVINE CHAMPION
                </div>

                <div className="relative mb-8">
                    <div className="absolute -inset-6 bg-amber-500 rounded-full blur-3xl opacity-20 animate-pulse"></div>
                    <img src={studentOfWeek.avatar} className="relative w-36 h-36 rounded-[3rem] border-4 border-amber-400 shadow-[0_0_50px_rgba(245,158,11,0.3)] animate-float" />
                    <div className="absolute -bottom-3 -right-3 bg-white text-indigo-900 p-3 rounded-2xl shadow-2xl border-2 border-amber-400">
                        <ShieldCheck size={24} fill="currentColor"/>
                    </div>
                </div>

                <h3 className="text-4xl font-black tracking-tighter mb-4 text-gradient bg-gradient-to-r from-amber-200 via-amber-400 to-amber-200">{studentOfWeek.name}</h3>

