      <div className="relative group w-full flex flex-col items-center">
        <div className={`absolute -inset-16 blur-[100px] opacity-25 transition-all duration-1000 bg-gradient-to-tr ${PET_STAGES[petStage].color} ${isActive ? 'animate-pulse scale-125' : 'opacity-10'}`}></div>

        <div className="relative glass p-14 rounded-[5.5rem] border-white shadow-2xl flex flex-col items-center gap-6 bg-white/40 w-full max-w-sm border-2">
          {/* Audio Visualizer */}
          <div className="flex items-end gap-1 h-8 absolute top-10">
            {visualizerBars.map((_, i) => (
              <div 
                key={i} 
                className={`w-1 bg-indigo-400 rounded-full transition-all duration-300 ${isActive && activeAmbient ? 'animate-music-bar' : 'h-1'}`}
                style={{ animationDelay: `${i * 0.1}s`, height: isActive && activeAmbient ? '100%' : '4px' }}
              ></div>
            ))}
          </div>

          <div className="relative mt-4">
            <div className={`text-[11rem] animate-float drop-shadow-[0_20px_50px_rgba(0,0,0,0.1)] transition-all duration-700 ${isActive ? 'scale-110' : 'scale-100 grayscale-[10%]'}`}>
                {PET_STAGES[petStage].icon}
            </div>
          </div>

          <div className="text-center space-y-3">
            <div className={`px-6 py-1.5 rounded-full text-[10px] font-black uppercase tracking-[0.4em] bg-gradient-to-r text-white shadow-xl ${PET_STAGES[petStage].color}`}>
                {PET_STAGES[petStage].label}
            </div>
            <div className="text-8xl font-black text-slate-800 font-mono tracking-tighter tabular-nums">
                {formatTime(seconds)}
            </div>
          </div>
        </div>
      </div>

      {/* Control Buttons */}
      <div className="flex items-center gap-6 z-10">
        <button 
          onClick={() => {setIsActive(false); setSeconds(mode === 'study' ? 25*60 : 5*60); setPetStage(0);}} 
          className="p-6 bg-white rounded-[2.2rem] border-2 border-slate-50 shadow-xl text-slate-300 hover:text-rose-500 hover:border-rose-100 transition-all active:scale-90"
        >
          <RotateCcw size={32} strokeWidth={2.5}/>
        </button>

        <button 
          onClick={() => { ensureAudioEnabled(); setIsActive(!isActive); }} 
          className={`px-14 py-7 rounded-[3rem] font-black text-white shadow-2xl transition-all active:scale-95 flex items-center gap-4 text-2xl group ${
            isActive ? 'bg-slate-800 shadow-slate-200' : 'bg-indigo-600 shadow-indigo-300'
          }`}
        >
          {isActive ? <><Pause size={32} fill="currentColor"/> DỪNG</> : <><Play size={32} fill="currentColor" className="group-hover:translate-x-1 transition-transform"/> HỌC NGAY</>}
        </button>

        <button 
          onClick={() => setShowMusic(!showMusic)} 
          className={`p-6 rounded-[2.2rem] border-2 transition-all active:scale-90 ${showMusic ? 'bg-indigo-600 text-white border-indigo-500 shadow-indigo-200' : 'bg-white text-slate-300 border-slate-50 shadow-xl'}`}
