          <div className="flex items-center justify-between">
            <div>
              <h3 className="font-black text-2xl text-slate-800 tracking-tighter">Supreme Audio</h3>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Không gian tập trung tối thượng</p>
            </div>
            <button onClick={() => setShowMusic(false)} className="p-3 bg-slate-100 rounded-2xl text-slate-400 hover:text-slate-800 transition-colors"><X size={20}/></button>
          </div>

          <div className="grid grid-cols-2 gap-4">
             {AMBIENT_SOUNDS.map(sound => (
               <button 
                 key={sound.id}
                 onClick={() => toggleAmbient(sound)}
                 className={`p-6 rounded-[2.5rem] border-2 transition-all flex items-center gap-4 group ${activeAmbient === sound.id ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-[1.02]' : 'bg-slate-50 border-transparent text-slate-500 hover:bg-white hover:border-indigo-100'}`}
               >
                 <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${activeAmbient === sound.id ? 'bg-white/20' : 'bg-white shadow-sm group-hover:rotate-12'}`}>
                    <sound.icon size={24} />
                 </div>
                 <span className="font-black text-[11px] uppercase tracking-widest">{sound.name}</span>
               </button>
             ))}
          </div>

          <div className="bg-slate-100/50 p-6 rounded-[2.8rem] flex items-center gap-6 border border-slate-100">
             {volume === 0 ? <VolumeX size={22} className="text-slate-400" /> : <Volume2 size={22} className="text-indigo-600" />}
             <input 
               type="range" min="0" max="1" step="0.01" value={volume} 
               onChange={(e) => {
                 const v = parseFloat(e.target.value);
                 setVolume(v);
                 if (audioRef.current) audioRef.current.volume = v;
