// Helper for Live API
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) { binary += String.fromCharCode(bytes[i]); }
  return btoa(binary);
}

const AITutor: React.FC<{ userData: UserProfile; onExp: (amount: number) => void }> = ({ userData, onExp }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isLive, setIsLive] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sessionRef = useRef<any>(null);

  const toggleLiveMode = async () => {
    if (isLive) {
      if (sessionRef.current) sessionRef.current.close();
      setIsLive(false);
      return;
    }

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const inputCtx = new AudioContext({ sampleRate: 16000 });
      const outputCtx = new AudioContext({ sampleRate: 24000 });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            const source = inputCtx.createMediaStreamSource(stream);
            const processor = inputCtx.createScriptProcessor(4096, 1, 1);
            processor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) { int16[i] = inputData[i] * 32768; }
              sessionPromise.then(s => s.sendRealtimeInput({ media: { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } }));
            };
            source.connect(processor);
            processor.connect(inputCtx.destination);
            setIsLive(true);
            showToast("Hệ thống âm thanh Live đã sẵn sàng!");
          },
          onmessage: async (msg) => {
            // Process audio response logic would go here
          },
          onerror: (e) => setIsLive(false)
        },
        config: { responseModalities: [Modality.AUDIO], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } } }
      });
      sessionRef.current = await sessionPromise;
    } catch (e) {
      alert("Vui lòng cấp quyền Microphone để dùng tính năng này!");
    }
  };

  const showToast = (m: string) => console.log(m);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  const handleSend = async (customText?: string) => {
    const textToSend = customText || input;
    if ((!textToSend.trim() && !selectedImage) || isTyping) return;

    const userText = textToSend.trim();
    const imageToProcess = selectedImage;
    setInput('');
    setSelectedImage(null);

    setMessages(prev => [...prev, { role: 'user', text: imageToProcess ? `[Ảnh] ${userText}` : userText, timestamp: Date.now() }]);
    setIsTyping(true);

    try {
      const replyText = imageToProcess 
        ? await analyzeStudyImage(imageToProcess, userText || "Giải thích ảnh này")
        : await getTutorResponse(userText);
      setMessages(prev => [...prev, { role: 'ai', text: replyText, timestamp: Date.now() }]);
      onExp(15);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'ai', text: "Lỗi kết nối AI, thử lại nhé!", timestamp: Date.now() }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#F4F7FF]/30 relative overflow-hidden">
      {/* Live Mode Overlay */}
      {isLive && (
        <div className="absolute inset-0 z-50 bg-indigo-950/90 backdrop-blur-2xl flex flex-col items-center justify-center p-10 animate-fade-in">
           <div className="relative mb-10">
              <div className="absolute inset-0 bg-indigo-500 rounded-full blur-[60px] animate-pulse"></div>
              <div className="relative w-40 h-40 bg-indigo-600 rounded-full flex items-center justify-center text-white shadow-[0_0_80px_rgba(99,102,241,0.5)] border-4 border-indigo-400">
                  <Mic size={64} className="animate-bounce" />
              </div>
              <div className="absolute -top-4 -right-4 bg-rose-500 text-white px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest animate-pulse">LIVE</div>
