import React, { useState, useEffect, useCallback } from 'react';
import { 
  Home, Zap, Trophy, Send, Sparkles, Heart, MessageCircle, 
  Plus, Bot, Stars, Search, Menu, X, Flame, Share2, 
  Edit3, Layout, Calculator, User, Award, Users, Settings,
  CheckCircle2, Crown, Ghost, BookOpen, GraduationCap,
  LogOut, ArrowRight, Bell, Clock, BrainCircuit, Target, 
  ThumbsUp, Smile, MoreHorizontal, ThumbsDown, Scale,
  ChevronRight, Calendar, LayoutGrid, FireExtinguisher,
  ShieldCheck, Globe, Facebook, Key, MessageSquare, Compass, 
  Star, CheckCircle, BarChart3, ListTodo
} from 'lucide-react';
import { UserProfile, AppTab, LoginMethod, DailyQuest } from './types';
import { getLevelInfo } from './constants';
import Feed from './components/Feed';
import AITutor from './components/AITutor';
import FocusZone from './components/FocusZone';
import QuizArena from './components/QuizArena';
import Leaderboard from './components/Leaderboard';
import Profile from './components/Profile';
import StudyTools from './components/StudyTools';

const INITIAL_QUESTS: DailyQuest[] = [
  { id: 'q1', text: 'Học tập trung 25 phút', target: 25, current: 0, reward: 100, isClaimed: false },
  { id: 'q2', text: 'Hỏi Gia sư AI 3 câu hỏi', target: 3, current: 0, reward: 50, isClaimed: false },
  { id: 'q3', text: 'Đăng 1 bài kiến thức mới', target: 1, current: 0, reward: 30, isClaimed: false }
];

const App: React.FC = () => {
  const [userData, setUserData] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.FEED);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [showStreakModal, setShowStreakModal] = useState(false);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  useEffect(() => {
    const savedData = localStorage.getItem('studygram_user');
    if (savedData) {
      const parsedData = JSON.parse(savedData) as UserProfile;
      const today = new Date().toDateString();
      const lastLoginDate = parsedData.lastLogin ? new Date(parsedData.lastLogin).toDateString() : "";
      if (today !== lastLoginDate) parsedData.dailyQuests = INITIAL_QUESTS;
      setUserData(parsedData);
      checkStreak(parsedData);
    }
    setTimeout(() => setIsLoading(false), 2000); 
  }, []);

  const checkStreak = (user: UserProfile) => {
    const now = new Date().setHours(0,0,0,0);
    const last = user.lastLogin ? new Date(user.lastLogin).setHours(0,0,0,0) : 0;
    if (now > last) setShowStreakModal(true);
  };

  const showToast = useCallback((message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  }, []);

  const handleUpdateUser = (updated: UserProfile) => {
    setUserData(updated);
    localStorage.setItem('studygram_user', JSON.stringify(updated));
  };

  const handleAddExp = useCallback((amount: number) => {
    setUserData(prev => {
        if (!prev) return null;
        const updated = { ...prev, exp: prev.exp + amount };
        localStorage.setItem('studygram_user', JSON.stringify(updated));
        return updated;
    });
    showToast(`+${amount} EXP!`, 'success');
  }, [showToast]);

  const updateQuestProgress = (questId: string, amount: number) => {
    if (!userData) return;
    const updatedQuests = userData.dailyQuests.map(q => 
      q.id === questId ? { ...q, current: Math.min(q.target, q.current + amount) } : q
    );
    handleUpdateUser({ ...userData, dailyQuests: updatedQuests });
  };

  const claimQuestReward = (questId: string) => {
    if (!userData) return;
    const quest = userData.dailyQuests.find(q => q.id === questId);
    if (quest && quest.current >= quest.target && !quest.isClaimed) {
      const updatedQuests = userData.dailyQuests.map(q => 
        q.id === questId ? { ...q, isClaimed: true } : q
      );
      handleAddExp(quest.reward);
      handleUpdateUser({ ...userData, dailyQuests: updatedQuests });
      // @ts-ignore
      window.confetti({ particleCount: 50, spread: 60, origin: { y: 0.8 } });
    }
  };

  const handleAuth = (method: LoginMethod, name?: string) => {
    const newUser: UserProfile = {
      uid: 'u-' + Math.random().toString(36).slice(2, 7),
      name: name || 'Học giả Ẩn danh',
      avatar: `https://api.dicebear.com/7.x/notionists/svg?seed=${name || method}-${Math.random()}`,
      exp: 0, bio: 'Sẵn sàng chinh phục tri thức 🚀', joinedAt: Date.now(), streak: 1, completedQuizzes: 0, 
      loginMethod: method, isVerified: method !== 'guest', dailyQuests: INITIAL_QUESTS,
      skills: { criticalThinking: 20, focus: 20, creativity: 20, knowledge: 20, discipline: 20 }
    };
    setUserData(newUser);
    localStorage.setItem('studygram_user', JSON.stringify(newUser));
  };

  if (isLoading) return <LoadingScreen />;
  if (!userData) return <AuthScreen onAuth={handleAuth} />;

  return (
    <div className="min-h-screen text-slate-800 font-sans selection:bg-indigo-100 flex flex-col overflow-x-hidden">
      {toast && <Toast toast={toast} />}
      {showStreakModal && <StreakModal streak={userData.streak + 1} onClaim={() => {
        handleUpdateUser({ ...userData, streak: userData.streak + 1, exp: userData.exp + 50, lastLogin: Date.now() });
        setShowStreakModal(false);
        // @ts-ignore
        window.confetti({ particleCount: 150, spread: 80, origin: { y: 0.6 } });
      }} />}

      <Sidebar 
        isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} 
        userData={userData} setActiveTab={setActiveTab} activeTab={activeTab} 
        onLogout={() => { localStorage.removeItem('studygram_user'); setUserData(null); }}
      />

      <Header onOpenMenu={() => setSidebarOpen(true)} userData={userData} activeTab={activeTab} />

      <main className={`flex-1 w-full max-w-4xl mx-auto transition-all duration-500 ${activeTab === AppTab.TUTOR ? 'h-[calc(100vh-80px-100px)] overflow-hidden' : 'p-4 md:p-8 pb-32 mt-20'}`}>
        {activeTab === AppTab.FEED && <ZenDashboard userData={userData} onClaim={claimQuestReward} />}
        {activeTab === AppTab.FEED && <Feed userData={userData} onExp={(n) => { handleAddExp(n); updateQuestProgress('q3', 1); }} />}
        {activeTab === AppTab.TUTOR && <AITutor userData={userData} onExp={(n) => { handleAddExp(n); updateQuestProgress('q2', 1); }} />}
        {activeTab === AppTab.FOCUS && <FocusZone onExp={(n) => { handleAddExp(n); updateQuestProgress('q1', 25); }} showToast={showToast} />}
        {activeTab === AppTab.TOOLS && <StudyTools onExp={handleAddExp} />}
        {activeTab === AppTab.QUIZ && <QuizArena onExp={handleAddExp} showToast={showToast} />}
        {activeTab === AppTab.RANK && <Leaderboard currentUid={userData.uid} userData={userData} />}
        {activeTab === AppTab.PROFILE && <Profile userData={userData} onUpdate={handleUpdateUser} onToast={showToast} />}
      </main>

      <BottomNav activeTab={activeTab} setActiveTab={setActiveTab} />
    </div>
  );
};

const ZenDashboard: React.FC<{ userData: UserProfile; onClaim: (id: string) => void }> = ({ userData, onClaim }) => {
  const [goal, setGoal] = useState('');
  const [goals, setGoals] = useState<{id: string, text: string, done: boolean}[]>([]);

  useEffect(() => {
    const savedGoals = localStorage.getItem(`goals_${userData.uid}`);
    if (savedGoals) setGoals(JSON.parse(savedGoals));
  }, []);

  const addGoal = () => {
    if (!goal.trim()) return;
    const newGoals = [...goals, { id: Date.now().toString(), text: goal, done: false }];
    setGoals(newGoals);
    localStorage.setItem(`goals_${userData.uid}`, JSON.stringify(newGoals));
    setGoal('');
  };

  const toggleGoal = (id: string) => {
    const newGoals = goals.map(g => g.id === id ? {...g, done: !g.done} : g);
    setGoals(newGoals);
    localStorage.setItem(`goals_${userData.uid}`, JSON.stringify(newGoals));
  };

  return (
    <div className="mb-12 space-y-6 animate-slide-up">
      <div className="flex items-center justify-between px-2">
         <div>
           <h2 className="text-3xl font-black text-slate-800 tracking-tighter">AI Goal Mastery</h2>
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Kế hoạch chinh phục đỉnh cao</p>
         </div>
         <div className="flex items-center gap-2 bg-indigo-600 px-5 py-2.5 rounded-2xl text-white shadow-xl">
            <Star size={18} fill="currentColor" />
            <span className="text-sm font-black">{userData.exp} XP</span>
         </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="glass p-8 rounded-[3rem] border-white shadow-xl bg-white/60">
           <div className="flex items-center gap-3 mb-6">
              <ListTodo size={20} className="text-indigo-600" />
              <h4 className="text-sm font-black text-slate-800 uppercase tracking-widest">Mục tiêu hôm nay</h4>
           </div>
           <div className="flex gap-2 mb-6">
              <input value={goal} onChange={e => setGoal(e.target.value)} onKeyDown={e => e.key === 'Enter' && addGoal()} placeholder="VD: Giải 5 bài Toán..." className="flex-1 bg-slate-50 rounded-2xl px-4 py-3 text-xs font-bold outline-none border-2 border-transparent focus:border-indigo-100 transition-all" />
              <button onClick={addGoal} className="p-3 bg-indigo-600 text-white rounded-2xl"><Plus size={20}/></button>
           </div>
           <div className="space-y-3 max-h-40 overflow-y-auto no-scrollbar">
              {goals.map(g => (
                <div key={g.id} onClick={() => toggleGoal(g.id)} className={`flex items-center gap-3 p-4 rounded-2xl cursor-pointer transition-all ${g.done ? 'bg-green-50 text-green-600 opacity-60' : 'bg-white shadow-sm border border-slate-50'}`}>
                   {g.done ? <CheckCircle size={18} /> : <div className="w-4 h-4 rounded-full border-2 border-slate-200"></div>}
                   <span className={`text-xs font-bold ${g.done ? 'line-through' : ''}`}>{g.text}</span>
                </div>
              ))}
              {goals.length === 0 && <p className="text-center text-[10px] text-slate-400 font-black py-4 uppercase tracking-widest italic">Chưa có mục tiêu nào...</p>}
           </div>
        </div>

        <div className="grid grid-cols-1 gap-4">
          {userData.dailyQuests.map(quest => (
            <div key={quest.id} className={`glass p-6 rounded-[2.5rem] border-white shadow-sm transition-all relative overflow-hidden ${quest.isClaimed ? 'opacity-50' : 'hover:shadow-xl'}`}>
              <div className="relative z-10">
                <h4 className="text-[11px] font-black text-slate-800 mb-3 leading-tight">{quest.text}</h4>
                <div className="w-full h-1.5 bg-slate-100 rounded-full mb-3 overflow-hidden">
                   <div className="h-full bg-indigo-600 transition-all duration-700" style={{ width: `${(quest.current / quest.target) * 100}%` }}></div>
                </div>
                <div className="flex justify-between items-center">
                   <span className="text-[10px] font-black text-slate-400">{quest.current}/{quest.target}</span>
                   {quest.current >= quest.target && !quest.isClaimed ? (
                     <button onClick={() => onClaim(quest.id)} className="bg-indigo-600 text-white px-4 py-1.5 rounded-full text-[10px] font-black animate-bounce shadow-lg">NHẬN XP</button>
                   ) : (
                     <span className="text-[9px] font-black text-indigo-500">+{quest.reward} XP</span>
                   )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

