              <div className="relative z-10">
                <div className="flex justify-between items-start mb-3">
                  <h4 className="text-[11px] font-black text-slate-800 leading-tight uppercase tracking-tight max-w-[70%]">{quest.text}</h4>
                  <span className="text-[9px] font-black text-indigo-500 bg-indigo-50 px-2 py-0.5 rounded-full">+{quest.reward} XP</span>
                </div>
                <div className="w-full h-1.5 bg-slate-100 rounded-full mb-3 overflow-hidden">
                   <div className="h-full bg-indigo-600 transition-all duration-700" style={{ width: `${(quest.current / quest.target) * 100}%` }}></div>
                </div>
                <div className="flex justify-between items-center">
                   <span className="text-[10px] font-black text-slate-400">{quest.current}/{quest.target}</span>
                   {quest.current >= quest.target && !quest.isClaimed && (
                     <button onClick={() => onClaim(quest.id)} className="bg-indigo-600 text-white px-5 py-2 rounded-full text-[10px] font-black animate-bounce shadow-lg shadow-indigo-200">NHẬN THƯỞNG</button>
                   )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
      <style>{`
        @keyframes phantom-glow {
          0%, 100% { filter: drop-shadow(0 0 15px rgba(99, 102, 241, 0.8)); transform: scale(1); }
          50% { filter: drop-shadow(0 0 30px rgba(168, 85, 247, 0.9)); transform: scale(1.05); }
        }
        @keyframes heartbeat {
          0% { transform: scale(1); }
          15% { transform: scale(1.2); }
          30% { transform: scale(1); }
          45% { transform: scale(1.2); }
          100% { transform: scale(1); }
        }
        .animate-phantom-glow { animation: phantom-glow 2s ease-in-out infinite; }
        .animate-heartbeat { animation: heartbeat 0.8s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

