import React, { useState } from 'react';
import { 
  Wand2, BookOpen, ListChecks, CalendarDays, 
  ChevronRight, ArrowLeft, Loader2, Sparkles, 
  Copy, Check, LayoutGrid, RotateCw, Download, FileText,
  Smile, ImageIcon, Network, ChevronDown, GraduationCap, Map,
  CheckCircle2, AlertCircle, Search, Globe, Filter
} from 'lucide-react';
import { 
  summarizeText, generateFlashcards, downloadAsFile, 
  generateMemeImage, generateMindMap, callGeminiWithRetry,
  getOfficialExamLinks, generateExamPaper
} from '../services/geminiService';

const StudyTools: React.FC<{ onExp: (amount: number) => void }> = ({ onExp }) => {
  const [activeTool, setActiveTool] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [result, setResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [examLinks, setExamLinks] = useState<any[]>([]);
  // Fix: Added grade to filters to ensure API calls have all required parameters
  const [filters, setFilters] = useState({ year: '2024', subject: 'Toán học', province: 'Hà Nội', grade: '12' });

  const tools = [
    { 
      id: 'exam_bank', 
      name: 'Kho Đề Sở GD', 
      desc: 'Truy tìm đề thi chính thức của các Sở GD qua các năm.', 
      icon: Globe, 
      color: 'bg-indigo-600',
      placeholder: 'Tìm kiếm đề thi (VD: Đề Toán 2024 Hà Nội)...'
    },
    { 
      id: 'quiz_creator', 
      name: 'AI Exam Generator', 
      desc: 'Tự động tạo bộ đề trắc nghiệm theo chuẩn Sở GD.', 
      icon: GraduationCap, 
      color: 'bg-rose-500',
      placeholder: 'Chủ đề ôn thi...'
    },
    { 
      id: 'mindmap', 
      name: 'Sơ đồ tư duy AI', 
      desc: 'Phân tích chủ đề thành sơ đồ tư duy logic.', 
      icon: Network, 
      color: 'bg-emerald-500',
      placeholder: 'Nhập chủ đề...'
    },
    { 
      id: 'summary', 
      name: 'Tóm tắt thông minh', 
      desc: 'Cô đọng văn bản dài thành các ý chính.', 
      icon: ListChecks, 
      color: 'bg-blue-500',
      placeholder: 'Dán văn bản vào đây...'
    }
  ];

  const handleRunTool = async () => {
    if (!input.trim() && activeTool !== 'exam_bank') return;
    setLoading(true);
    setResult(null);
    setExamLinks([]);

    try {
      if (activeTool === 'exam_bank') {
        // Fix: Added missing 4th argument 'grade' to getOfficialExamLinks
        const links = await getOfficialExamLinks(filters.subject, filters.year, filters.province, filters.grade);
        setExamLinks(links);
        onExp(10);
      } else if (activeTool === 'quiz_creator') {
        // Fix: Added missing arguments to generateExamPaper (subject, grade, difficulty)
        const res = await generateExamPaper(input || filters.subject, filters.grade, "practice");
        setResult(res);
        onExp(30);
      } else if (activeTool === 'mindmap') {
        const res = await generateMindMap(input);
        setResult(res);
        onExp(20);
      } else if (activeTool === 'summary') {
        const res = await summarizeText(input);
        setResult(res);
        onExp(15);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-8 animate-slide-up max-w-2xl mx-auto w-full pb-32">
      {activeTool ? (
        <div className="animate-slide-in">
          <button onClick={() => { setActiveTool(null); setResult(null); setInput(''); setExamLinks([]); }} className="flex items-center gap-2 text-slate-400 hover:text-indigo-600 mb-6 font-black text-[10px] uppercase tracking-widest transition-colors"><ArrowLeft size={16} /> Quay lại</button>

          <div className="glass rounded-[3rem] p-8 mb-8 border-2 border-white shadow-xl bg-white/60">
            <h3 className="font-black text-xl mb-6 text-slate-800 flex items-center gap-3">
              {tools.find(t => t.id === activeTool)?.name}
              {activeTool === 'exam_bank' && <span className="bg-indigo-100 text-indigo-600 px-3 py-1 rounded-full text-[10px] animate-pulse">LIVE SEARCH</span>}
            </h3>

            {activeTool === 'exam_bank' && (
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
                <select value={filters.year} onChange={e => setFilters({...filters, year: e.target.value})} className="bg-slate-50 p-4 rounded-2xl font-black text-xs outline-none border-2 border-transparent focus:border-indigo-100">
                  {['2024', '2023', '2022', '2021', '2020'].map(y => <option key={y} value={y}>Năm {y}</option>)}
                </select>
                <select value={filters.subject} onChange={e => setFilters({...filters, subject: e.target.value})} className="bg-slate-50 p-4 rounded-2xl font-black text-xs outline-none border-2 border-transparent focus:border-indigo-100">
                  {['Toán học', 'Ngữ văn', 'Tiếng Anh', 'Vật lý', 'Hóa học', 'Sinh học', 'Lịch sử', 'Địa lý'].map(s => <option key={s} value={s}>{s}</option>)}
                </select>
                <select value={filters.province} onChange={e => setFilters({...filters, province: e.target.value})} className="bg-slate-50 p-4 rounded-2xl font-black text-xs outline-none border-2 border-transparent focus:border-indigo-100">
                  {['Hà Nội', 'TP.HCM', 'Đà Nẵng', 'Hải Phòng', 'Cần Thơ', 'Nghệ An', 'Nam Định'].map(p => <option key={p} value={p}>{p}</option>)}
                </select>
                <select value={filters.grade} onChange={e => setFilters({...filters, grade: e.target.value})} className="bg-slate-50 p-4 rounded-2xl font-black text-xs outline-none border-2 border-transparent focus:border-indigo-100">
                  {['10', '11', '12'].map(g => <option key={g} value={g}>Lớp {g}</option>)}
                </select>
              </div>
            )}

            <textarea 
              value={input} 
              onChange={e => setInput(e.target.value)} 
              placeholder={tools.find(t => t.id === activeTool)?.placeholder} 
              className="w-full h-32 bg-slate-50 rounded-2xl p-4 outline-none border-2 border-transparent focus:border-indigo-100 transition-all mb-4 font-bold text-sm"
            />

            <button onClick={handleRunTool} disabled={loading} className={`w-full py-5 rounded-[1.8rem] text-white font-black shadow-lg transition-all flex items-center justify-center gap-3 ${tools.find(t => t.id === activeTool)?.color}`}>
               {loading ? <RotateCw className="animate-spin"/> : <Sparkles size={20}/>} {loading ? 'Đang truy lục dữ liệu...' : 'BẮT ĐẦU TRUY VẤN'}
            </button>
          </div>

          {(result || examLinks.length > 0) && (
            <div className="glass rounded-[3.5rem] p-8 border-2 border-white shadow-2xl animate-slide-up bg-white/80">
               {activeTool === 'exam_bank' && (
                 <div className="space-y-4">
                    <h4 className="font-black text-indigo-600 text-[10px] uppercase tracking-widest mb-4 flex items-center gap-2">KẾT QUẢ TỪ CƠ SỞ DỮ LIỆU SỞ GD</h4>
                    {examLinks.map((link, i) => (
                      <a key={i} href={link.web?.uri} target="_blank" rel="noreferrer" className="block p-5 bg-white border border-slate-100 rounded-3xl hover:border-indigo-400 hover:shadow-lg transition-all group">
                         <div className="flex items-center justify-between">
                            <span className="font-bold text-sm text-slate-700 group-hover:text-indigo-600">{link.web?.title || "Tài liệu đề thi"}</span>
                            <Globe size={18} className="text-slate-300 group-hover:text-indigo-600" />
                         </div>
                         <p className="text-[10px] text-slate-400 mt-2 truncate">{link.web?.uri}</p>
                      </a>
                    ))}
                    {examLinks.length === 0 && <p className="text-center py-6 text-slate-400 font-bold italic text-sm">Không tìm thấy đề thi khớp với bộ lọc...</p>}
                 </div>
               )}

               {activeTool === 'quiz_creator' && Array.isArray(result) && (
                 <div className="space-y-8">
                    {result.map((q, i) => (
                      <div key={i} className="p-6 bg-slate-50 rounded-[2.5rem] border border-slate-100 relative shadow-inner">
                         <p className="font-black text-slate-800 text-base mb-4">Câu {i+1}: {q.question}</p>
                         <div className="grid grid-cols-1 gap-2">
                            {q.options.map((opt: string, idx: number) => (
                              <button key={idx} className="p-4 bg-white border border-slate-100 rounded-2xl text-left text-xs font-bold text-slate-600 hover:bg-indigo-50 transition-all">
                                 {opt}
                              </button>
                            ))}
                         </div>
                      </div>
                    ))}
                 </div>
               )}

               {activeTool === 'summary' && typeof result === 'string' && (
                 <div className="p-6 bg-white/50 rounded-3xl border border-indigo-100 italic font-bold text-slate-700 leading-relaxed">
                    {result}
                 </div>
               )}
            </div>
          )}
        </div>
      ) : (
        <>
          <div className="text-center py-6">
            <h2 className="text-4xl font-black text-slate-800 tracking-tighter mb-2">SUPREME TOOLS</h2>
            <p className="text-slate-400 font-black text-[10px] uppercase tracking-[0.4em]">Kho tri thức Sở GD chính thức</p>
          </div>
          <div className="grid grid-cols-1 gap-4">
            {tools.map(tool => (
              <button key={tool.id} onClick={() => setActiveTool(tool.id)} className="glass p-7 rounded-[3rem] border-white shadow-sm hover:shadow-2xl hover:translate-y-[-4px] transition-all flex items-center gap-6 group text-left border-2 bg-white/60">
                <div className={`w-16 h-16 ${tool.color} text-white rounded-[1.8rem] flex items-center justify-center shadow-lg group-hover:rotate-12 transition-transform`}>
                  <tool.icon size={32} />
                </div>
                <div className="flex-1">
                  <h3 className="font-black text-slate-800 text-lg mb-1">{tool.name}</h3>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">{tool.desc}</p>
                </div>
                <ChevronRight size={24} className="text-slate-200 group-hover:text-indigo-600" />
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
};

export default StudyTools;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Target, Rocket, Map, Activity, Calendar, 
  ChevronRight, Brain, AlertTriangle, CheckCircle,
  Loader2, Sparkles, Trophy, Book, BarChart3, FastForward,
  Shield, Sword, Heart, RefreshCw, Zap, GraduationCap,
  Filter, BookOpen, Layers, ArrowLeft, Globe
} from 'lucide-react';
import { UserProfile, StudyMission, Grade, ExamDifficulty } from '../types';
import { generateExamRoadmap, generateExamPaper, callGeminiWithRetry } from '../services/geminiService';

const MissionControl: React.FC<{ userData: UserProfile; onUpdate: (u: UserProfile) => void }> = ({ userData, onUpdate }) => {
  const [loading, setLoading] = useState(false);
  const [grade, setGrade] = useState<Grade>('12');
  const [subject, setSubject] = useState('Toán học');
  const [activeExam, setActiveExam] = useState<any[] | null>(null);
  const [examLoading, setExamLoading] = useState(false);
  const [bossChallenge, setBossChallenge] = useState<string | null>(null);
  const [bossLoading, setBossLoading] = useState(false);

  const generateBossChallenge = useCallback(async () => {
    setBossLoading(true);
    try {
      const challenge = await callGeminiWithRetry(`Tạo 1 thử thách học tập Vận dụng cao (9+) cực khó lớp ${grade} môn ${subject}. Trả lời cực ngắn 1 câu.`);
      setBossChallenge(challenge);
    } catch (e) {
      setBossChallenge("Giải quyết bài tập khó nhất trong đề thi năm nay!");
    } finally {
      setBossLoading(false);
    }
  }, [subject, grade]);

  useEffect(() => {
    if (userData.currentMission && !bossChallenge) {
      generateBossChallenge();
    }
  }, [userData.currentMission]);

  const startMission = async () => {
    setLoading(true);
    try {
      const roadmapData = await generateExamRoadmap(grade, subject);
      const newMission: StudyMission = {
        goal: 'THPTQG',
        grade: grade,
        targetDate: Date.now() + 60 * 24 * 60 * 60 * 1000,
        subject: subject,
        roadmap: roadmapData.roadmap.map((n: any, i: number) => ({
          ...n,
          status: i === 0 ? 'current' : 'locked'
        }))
      };
      onUpdate({ ...userData, currentMission: newMission });
    } finally {
      setLoading(false);
    }
  };

  const loadExam = async (difficulty: ExamDifficulty) => {
    setExamLoading(true);
    try {
      const exam = await generateExamPaper(subject, grade, difficulty);
      setActiveExam(exam);
    } catch (e) {
      setActiveExam([]);
    } finally {
      setExamLoading(false);
    }
  };

  const completeBoss = () => {
    const updated = { ...userData, streakShields: Math.min(userData.streakShields + 1, 3), exp: userData.exp + 300 };
    onUpdate(updated);
    setBossChallenge(null);
    // @ts-ignore
    window.confetti({ particleCount: 200, spread: 80, origin: { y: 0.6 } });
  };

  if (activeExam) {
    return (
      <div className="space-y-8 animate-slide-in pb-32">
        <button onClick={() => setActiveExam(null)} className="flex items-center gap-2 text-slate-400 hover:text-indigo-600 mb-6 font-black text-[10px] uppercase tracking-widest transition-colors">
          <ArrowLeft size={16} /> QUAY LẠI SẢNH ĐỀ
        </button>
        <div className="glass p-10 rounded-[4rem] border-white shadow-2xl bg-white/60">
           <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-800 tracking-tighter">BỘ ĐỀ THỰC CHIẾN LỚP {grade}</h3>
              <span className="bg-indigo-600 text-white px-5 py-2 rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg">MÔN {subject.toUpperCase()}</span>
           </div>
           <div className="space-y-10">
              {activeExam.map((q, i) => (
                <div key={i} className="p-8 bg-white/50 rounded-[3rem] border border-white shadow-inner animate-slide-up" style={{ animationDelay: `${i * 0.1}s` }}>
                   <p className="font-black text-slate-800 text-lg mb-6 leading-relaxed"><span className="text-indigo-600 mr-2">CÂU {i+1}:</span> {q.question}</p>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                      {q.options.map((opt: string, idx: number) => (
                        <button key={idx} className="p-5 bg-white border border-slate-100 rounded-2xl text-left text-sm font-bold text-slate-600 hover:bg-indigo-50 hover:border-indigo-400 transition-all flex items-center gap-3">
                           <div className="w-8 h-8 rounded-lg bg-slate-50 flex items-center justify-center text-[10px] font-black shrink-0">{String.fromCharCode(65 + idx)}</div>
                           {opt}
                        </button>
                      ))}
                   </div>
                </div>
              ))}
           </div>
           <button onClick={() => { setActiveExam(null); onUpdate({...userData, exp: userData.exp + 100}); }} className="w-full mt-10 py-6 bg-indigo-600 text-white rounded-[2.5rem] font-black text-sm uppercase tracking-[0.2em] shadow-2xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95">HOÀN THÀNH & NHẬN XP</button>
        </div>
      </div>
    );
  }

  if (!userData.currentMission) {
    return (
      <div className="space-y-10 animate-slide-up max-w-2xl mx-auto py-10">
        <div className="text-center space-y-4">
          <div className="w-24 h-24 bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-[2.8rem] flex items-center justify-center text-white mx-auto shadow-2xl animate-float">
             <GraduationCap size={48} strokeWidth={2.5}/>
          </div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tighter leading-none">SIÊU KHO ĐỀ 10-12</h2>
          <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">Cá nhân hóa theo khối lớp và mục tiêu của fen</p>
        </div>

        <div className="grid grid-cols-3 gap-4">
          {['10', '11', '12'].map(g => (
            <button 
              key={g} 
              onClick={() => setGrade(g as Grade)}
              className={`p-6 rounded-[2.5rem] border-4 transition-all ${grade === g ? 'bg-indigo-600 text-white border-indigo-200 shadow-xl scale-105' : 'bg-white text-slate-400 border-white hover:border-indigo-100'}`}
            >
               <span className="text-[10px] font-black block uppercase tracking-widest mb-1 opacity-60">KHỐI</span>
               <span className="text-3xl font-black">LỚP {g}</span>
            </button>
          ))}
        </div>

        <div className="bg-white p-7 rounded-[3.5rem] shadow-xl border-2 border-slate-50 relative group">
          <div className="absolute top-0 left-0 p-10 opacity-5 group-hover:rotate-12 transition-transform"><Book size={100}/></div>
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4 mb-3 block">CHỌN MÔN CHIẾN ĐẤU</label>
          <select 
            value={subject} 
            onChange={(e) => setSubject(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-2xl p-6 font-black text-slate-800 outline-none focus:ring-4 focus:ring-indigo-50 transition-all appearance-none cursor-pointer relative z-10"
          >
            {['Toán học', 'Ngữ văn', 'Tiếng Anh', 'Vật lý', 'Hóa học', 'Sinh học', 'Lịch sử', 'Địa lý'].map(s => <option key={s} value={s}>{s}</option>)}
          </select>
          <div className="absolute right-10 bottom-11 pointer-events-none text-slate-300 z-10">
             <ChevronRight size={24} className="rotate-90" />
          </div>
        </div>

        <button 
