import { GoogleGenAI, Type } from "@google/genai";

const FLASH_MODEL = 'gemini-3-flash-preview';

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

// Cập nhật instruction để bám sát SGK mới 2018
const SYSTEM_CURRICULUM = `Bạn là chuyên gia giáo dục Việt Nam. 
NHIỆM VỤ: Cung cấp nội dung học tập bám sát CHƯƠNG TRÌNH GDPT 2018 (SGK Kết nối tri thức, Chân trời sáng tạo, Cánh diều).
PHONG CÁCH: Ngắn gọn, chuyên nghiệp, dễ hiểu cho học sinh lớp 10-12.
CẤU TRÚC ĐỀ THI: Cập nhật định hướng thi tốt nghiệp THPT mới từ năm 2025 (Trắc nghiệm nhiều lựa chọn, Trắc nghiệm đúng/sai, Trắc nghiệm trả lời ngắn).`;

export const getOfficialExamLinks = async (subject: string, year: string, province: string, grade: string): Promise<any[]> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Tìm link đề thi/tài liệu ôn tập lớp ${grade} môn ${subject} bám sát SGK mới (Chương trình 2018). Trích xuất URL và tiêu đề.`,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });
    return response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
  } catch (e) {
    return [];
  }
};

export const generateExamPaper = async (subject: string, grade: string, difficulty: string): Promise<any[]> => {
  const ai = getAIInstance();
  try {
    const prompt = `Tạo 5 câu hỏi lớp ${grade} môn ${subject} theo cấu trúc thi 2025 (SGK mới). 
    Mức độ: ${difficulty === 'hardcore' ? 'Vận dụng cao' : difficulty === 'theory' ? 'Nhận biết (Lý thuyết)' : 'Thông hiểu/Vận dụng'}.`;

    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `${prompt} Trả về JSON: [{question: string, options: [string], answer: string, explanation: string}]`,
      config: {
        systemInstruction: SYSTEM_CURRICULUM,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              answer: { type: Type.STRING },
              explanation: { type: Type.STRING }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (e) {
    return [];
  }
};

