export const callGeminiWithRetry = async (prompt: string, systemInstruction?: string): Promise<string> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction || SYSTEM_CURRICULUM,
        temperature: 0.7,
      },
    });
    return response.text || "Lỗi rồi fen!";
  } catch (error) {
    return "Đang bận học, thử lại sau...";
  }
};

