const MissionControl: React.FC<{ userData: UserProfile; onUpdate: (u: UserProfile) => void }> = ({ userData, onUpdate }) => {
  const [loading, setLoading] = useState(false);
  const [grade, setGrade] = useState<Grade>('12');
  const [subject, setSubject] = useState('Toán học');
  const [activeExam, setActiveExam] = useState<any[] | null>(null);
  const [examLoading, setExamLoading] = useState(false);
  const [bossChallenge, setBossChallenge] = useState<string | null>(null);

  const startMission = async () => {
    setLoading(true);
    try {
      const roadmapData = await generateExamRoadmap(grade, subject);
      const newMission: StudyMission = {
        goal: 'THPTQG',
        grade: grade,
        targetDate: Date.now() + 60 * 24 * 60 * 60 * 1000,
        subject: subject,
        roadmap: roadmapData.roadmap.map((n: any, i: number) => ({
          ...n,
          status: i === 0 ? 'current' : 'locked'
        }))
      };
      onUpdate({ ...userData, currentMission: newMission });
    } finally {
      setLoading(false);
    }
  };

  const loadExam = async (difficulty: ExamDifficulty) => {
    setExamLoading(true);
    try {
      const exam = await generateExamPaper(subject, grade, difficulty);
      setActiveExam(exam);
    } catch (e) {
      setActiveExam([]);
    } finally {
      setExamLoading(false);
    }
  };

  if (activeExam) {
    return (
      <div className="space-y-6 animate-slide-up pb-32 max-w-2xl mx-auto">
