        </button>
        <div className="bg-white rounded-3xl p-8 border border-slate-200 shadow-sm">
           <div className="mb-8">
              <span className="text-xs font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-3 py-1 rounded-full mb-2 inline-block">Môn {subject} - Lớp {grade}</span>
              <h3 className="text-2xl font-extrabold text-slate-800">Đề Luyện Thực Chiến SGK</h3>
           </div>

           <div className="space-y-8">
              {activeExam.map((q, i) => (
                <div key={i} className="p-6 bg-slate-50 rounded-2xl border border-slate-100">
                   <p className="font-bold text-slate-800 mb-4 text-lg">Câu {i+1}: {q.question}</p>
                   <div className="grid grid-cols-1 gap-3">
                      {q.options.map((opt: string, idx: number) => (
                        <button key={idx} className="p-4 bg-white border border-slate-200 rounded-xl text-left text-sm font-medium hover:border-indigo-400 hover:bg-indigo-50 transition-all flex items-center gap-3">
                           <span className="w-8 h-8 rounded-lg bg-slate-100 flex items-center justify-center text-xs font-bold">{String.fromCharCode(65 + idx)}</span>
                           {opt}
                        </button>
                      ))}
                   </div>
                </div>
              ))}
           </div>

           <button onClick={() => { setActiveExam(null); onUpdate({...userData, exp: userData.exp + 100}); }} className="w-full mt-8 py-5 bg-indigo-600 text-white rounded-2xl font-black shadow-lg hover:bg-indigo-700 transition-all">HOÀN THÀNH</button>
        </div>
      </div>
    );
  }

  if (!userData.currentMission) {
    return (
      <div className="space-y-8 animate-slide-up max-w-xl mx-auto py-10">
        <div className="text-center">
          <div className="w-20 h-20 bg-indigo-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-xl mb-6">
             <GraduationCap size={40} />
