                    isCompleted ? 'border-green-100 bg-green-50/30' : 
                    'border-slate-50 opacity-50 bg-slate-50/50 grayscale'
                  }`}
                >
                   <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white font-black shrink-0 shadow-lg transition-transform ${
                     isCompleted ? 'bg-green-500 rotate-12' : 
                     isCurrent ? 'bg-indigo-600 scale-110' : 
                     'bg-slate-300'
                   }`}>
                      {isLoadingThis ? <Loader2 className="animate-spin" size={20}/> : 
                       isCompleted ? <CheckCircle size={24}/> : 
                       isLocked ? <Lock size={20}/> : i + 1}
                   </div>
                   <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                         <span className={`text-[9px] font-black px-2 py-0.5 rounded-full uppercase tracking-tighter ${
                           isCompleted ? 'bg-green-200 text-green-700' : 'bg-slate-200 text-slate-500'
                         }`}>
                            {node.difficulty === 'theory' ? 'Lý thuyết' : node.difficulty === 'practice' ? 'Luyện tập' : 'Phá đảo'}
                         </span>
                      </div>
                      <h5 className={`font-black text-base truncate tracking-tight ${isCurrent ? 'text-slate-800' : 'text-slate-500'}`}>
                        {node.title}
                      </h5>
                   </div>
                   {!isLocked && !isLoadingThis && <ChevronRight size={20} className={isCurrent ? 'text-indigo-600' : 'text-slate-300'} />}
                </button>
             );
          })}
       </div>

       <button onClick={() => onUpdate({...userData, currentMission: undefined})} className="w-full py-4 text-slate-400 font-black text-[10px] uppercase tracking-[0.3em] hover:text-rose-500 transition-colors">
          THIẾT LẬP LẠI LỘ TRÌNH
       </button>
    </div>
  );
};

export default MissionControl;

import { GoogleGenAI, Type } from "@google/genai";

const FLASH_MODEL = 'gemini-3-flash-preview';

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const SYSTEM_CURRICULUM = `Bạn là trợ lý giáo dục cao cấp tại Việt Nam. 
QUY TẮC BẮT BUỘC:
1. Chỉ sử dụng kiến thức từ Chương trình GDPT 2018 (SGK Kết nối tri thức, Chân trời sáng tạo, Cánh diều).
2. Tuyệt đối không dùng kiến thức chương trình cũ 2006.
3. Cấu trúc câu hỏi trắc nghiệm phải bám sát định hướng thi tốt nghiệp THPT từ năm 2025.
4. Trả lời cực kỳ ngắn gọn, súc tích, chuyên nghiệp.
5. Luôn ưu tiên các ví dụ thực tế trong đời sống Việt Nam.`;

export const generateExamRoadmap = async (grade: string, subject: string): Promise<any> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Tạo lộ trình 5 bước ôn tập môn ${subject} lớp ${grade} (SGK mới 2018). 
      Format JSON: {roadmap: [{id: string, title: string, difficulty: 'theory'|'practice'|'hardcore', topics: string[]}]}`,
      config: {
        systemInstruction: SYSTEM_CURRICULUM,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            roadmap: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  title: { type: Type.STRING },
                  difficulty: { type: Type.STRING },
                  topics: { type: Type.ARRAY, items: { type: Type.STRING } }
                }
              }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (e) {
    return { roadmap: [] };
  }
};

export const generateExamPaper = async (subject: string, grade: string, difficulty: string, count: number = 20): Promise<any[]> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Tạo đúng ${count} câu hỏi trắc nghiệm lớp ${grade} môn ${subject} bám sát SGK mới 2018, độ khó: ${difficulty}. 
      JSON format: [{question: string, options: [string], answer: string, explanation: string}]`,
      config: {
        systemInstruction: SYSTEM_CURRICULUM,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              answer: { type: Type.STRING },
              explanation: { type: Type.STRING }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (e) {
    return [];
  }
};

export const callGeminiWithRetry = async (prompt: string, systemInstruction?: string): Promise<string> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction || SYSTEM_CURRICULUM,
        temperature: 0.7,
      },
    });
    return response.text || "Đã xảy ra lỗi hệ thống.";
  } catch (error) {
    return "Hệ thống đang quá tải, vui lòng thử lại.";
  }
};

