                  <select value={filters.province} onChange={e => setFilters({...filters, province: e.target.value})} className="bg-slate-50 p-4 rounded-2xl font-black text-xs outline-none border-2 border-transparent focus:border-indigo-100">
                    {['Hà Nội', 'TP.HCM', 'Đà Nẵng', 'Hải Phòng', 'Cần Thơ', 'Nghệ An', 'Nam Định'].map(p => <option key={p} value={p}>{p}</option>)}
