               {activeTool === 'quiz_creator' && Array.isArray(result) && (
                 <div className="space-y-8">
                    {result.map((q, i) => (
                      <div key={i} className="p-6 bg-slate-50 rounded-[2.5rem] border border-slate-100 relative shadow-inner">
