import React, { useState, useEffect, useCallback, memo } from 'react';
import { 
  Plus, Heart, Sparkles, MessageSquare, X, Send, 
  ShieldCheck, Share2
} from 'lucide-react';
import { Post, UserProfile, PostType } from '../types';
import { checkVibePost, suggestHashtags } from '../services/geminiService';
import MarkdownText from './MarkdownText';

const Feed: React.FC<{ userData: UserProfile; onExp: (n: number) => void }> = ({ userData, onExp }) => {
  const [posts, setPosts] = useState<Post[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<PostType | 'all'>('all');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Load posts once
  useEffect(() => {
    try {
      const saved = localStorage.getItem('studygram_posts');
      if (saved) {
        const parsed = JSON.parse(saved);
        const validatedPosts = parsed.map((p: any) => ({
          ...p,
          likes: Array.isArray(p.likes) ? p.likes : [],
          comments: Array.isArray(p.comments) ? p.comments : [],
          hashtags: Array.isArray(p.hashtags) ? p.hashtags : [],
          aiAnalysis: p.aiAnalysis || ''
        }));
        setPosts(validatedPosts);
      } else {
        const initial = [{
          id: 'p1', uid: 'admin', userName: 'Hệ thống StudyGram 🛡️', avatar: 'https://api.dicebear.com/7.x/notionists/svg?seed=Admin',
          content: 'Chào mừng các học giả tới phiên bản **StudyGram V7 Performance**! 🚀\n\nĐã tối ưu hóa tốc độ xử lý, giảm lag và tăng trải nghiệm lướt siêu mượt. Hãy chia sẻ kiến thức ngay nào! 🔥', category: 'Thông báo', type: 'event' as PostType, mood: '🚀', createdAt: Date.now(), likes: [], comments: [], isPinned: true, aiAnalysis: 'Hệ thống đang hoạt động với hiệu suất tối đa!'
        }];
        setPosts(initial);
      }
    } catch (e) {
      console.error("Error loading posts:", e);
      setPosts([]);
    }
  }, []);

  // Save posts to localStorage whenever they change
  useEffect(() => {
    if (posts.length > 0) {
      localStorage.setItem('studygram_posts', JSON.stringify(posts));
    }
  }, [posts]);

  const filteredPosts = posts.filter(p => activeTab === 'all' || p.type === activeTab);

  const handleAddPost = async (data: Partial<Post>) => {
    setIsAnalyzing(true);
    try {
      // Async operations
      const hashtags = await suggestHashtags(data.content!);
      const vibeData = await checkVibePost(data.content!);

      const newPost: Post = {
        id: Date.now().toString(), uid: userData.uid, userName: userData.name, avatar: userData.avatar,
        content: data.content!, category: data.category!, type: data.type || 'knowledge', mood: data.mood || '📚',
        createdAt: Date.now(), likes: [], comments: [], hashtags, aiAnalysis: vibeData.comment
      };

      setPosts(prev => [newPost, ...prev]);
      onExp(25);
      setIsModalOpen(false);
    } finally {
      setIsAnalyzing(false);
    }
  };

  // Optimize: useCallback ensures function reference implies stability
  const handleLike = useCallback((id: string) => {
    setPosts(currentPosts => 
      currentPosts.map(p => 
        p.id === id 
          ? { ...p, likes: p.likes.includes(userData.uid) ? p.likes.filter(u => u !== userData.uid) : [...p.likes, userData.uid] } 
          : p
      )
    );
  }, [userData.uid]);

  // Optimize: useCallback
  const handleComment = useCallback((id: string, text: string) => {
    if (!text.trim()) return;
    setPosts(currentPosts => 
      currentPosts.map(p => 
        p.id === id 
          ? { ...p, comments: [...p.comments, { id: Date.now().toString(), userName: userData.name, avatar: userData.avatar, content: text, createdAt: Date.now(), isAuthor: true }] } 
          : p
      )
    );
    onExp(5);
  }, [userData.name, userData.avatar, onExp]);

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] animate-slide-up max-w-2xl mx-auto w-full">
      {/* Sticky Header Section */}
      <div className="space-y-6 pb-6 px-1">
        {/* Create Post Trigger */}
        <div className="glass p-6 rounded-[3rem] shadow-sm flex items-center gap-6 cursor-pointer hover:shadow-md transition-all border-white bg-white group transform-gpu" onClick={() => setIsModalOpen(true)}>
          <div className="relative shrink-0">
            <img src={userData.avatar} className="w-14 h-14 rounded-[1.5rem] border-2 border-white shadow-sm group-hover:rotate-6 transition-transform" />
            <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 border-2 border-white rounded-full"></div>
          </div>
          <div className="flex-1 text-slate-400 font-bold text-lg tracking-tight">Chia sẻ tri thức mới...</div>
          <div className="w-12 h-12 bg-indigo-600 text-white rounded-[1.2rem] flex items-center justify-center shadow-md shadow-indigo-100 group-hover:scale-110 transition-transform"><Plus size={24} strokeWidth={3}/></div>
        </div>

        {/* Filters */}
        <div className="flex gap-2 p-1.5 bg-white/60 backdrop-blur-md rounded-full w-full overflow-x-auto no-scrollbar border border-white/50 shadow-sm transform-gpu">
          {['all', 'knowledge', 'meme', 'event'].map(t => (
            <button 
              key={t} 
              onClick={() => setActiveTab(t as any)} 
              className={`flex-1 px-4 py-3 rounded-full text-[10px] font-black uppercase tracking-[0.2em] transition-all duration-300 whitespace-nowrap ${activeTab === t ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-800 hover:bg-white/50'}`}
            >
              {t === 'all' ? 'Tất cả' : t}
            </button>
          ))}
        </div>
      </div>

      {/* Standard Scrollable List */}
      <div className="flex-1 overflow-y-auto no-scrollbar pb-32 space-y-8 px-1">
        {filteredPosts.map((post) => (
          <PostCard 
            key={post.id}
            post={post} 
            userData={userData} 
            onLike={handleLike} 
            onComment={handleComment} 
          />
        ))}
        {filteredPosts.length === 0 && (
          <div className="text-center py-20 opacity-50 font-bold">Chưa có bài viết nào...</div>
        )}
      </div>

      {isModalOpen && (
        <CreatePostModal onClose={() => setIsModalOpen(false)} onSubmit={handleAddPost} userData={userData} isAnalyzing={isAnalyzing} />
      )}
    </div>
  );
};

// Optimized PostCard with Custom Comparison to prevent re-renders when parent state (like EXP) changes
const PostCard = memo(({ post, userData, onLike, onComment }: { post: Post, userData: UserProfile, onLike: (id: string) => void, onComment: (id: string, txt: string) => void }) => {
  const [showComments, setShowComments] = useState(false);
  const [input, setInput] = useState('');
  const [justShared, setJustShared] = useState(false);

  const likes = post.likes || [];
  const comments = post.comments || [];
  const hasLiked = likes.includes(userData.uid);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareText = `${post.userName} trên StudyGram:\n\n${post.content}\n\n#StudyGram #V7`;
    try {
      if (navigator.share) await navigator.share({ title: `Bài viết của ${post.userName}`, text: shareText, url: window.location.href });
      else {
        await navigator.clipboard.writeText(shareText);
        setJustShared(true); setTimeout(() => setJustShared(false), 2000);
      }
    } catch (err) {}
  };

  return (
    // Performance: Use solid bg-white instead of transparent glass for list items
    <div className="bg-white rounded-[3rem] p-6 md:p-10 border border-slate-100 shadow-lg relative overflow-hidden group transform-gpu">
      <div className="flex gap-4 mb-6">
        <div className="relative shrink-0">
          <img src={post.avatar} className="w-14 h-14 rounded-[1.8rem] border-2 border-slate-50 shadow-sm" loading="lazy" />
          <div className="absolute -bottom-1 -right-1 bg-white w-7 h-7 rounded-xl flex items-center justify-center text-sm shadow-sm border border-slate-50">{post.mood}</div>
        </div>
        <div className="flex flex-col justify-center min-w-0">
          <h4 className="font-black text-slate-800 text-base flex items-center gap-2 tracking-tight leading-none truncate">
            {post.userName} 
            {post.type === 'event' && <ShieldCheck size={16} className="text-amber-500 shrink-0" fill="currentColor"/>}
          </h4>
          <div className="flex items-center gap-2 mt-1.5">
            <span className="text-[9px] px-2 py-0.5 rounded-full font-black uppercase tracking-widest bg-indigo-50 text-indigo-600 border border-indigo-100 shrink-0">#{post.category}</span>
            <span className="text-[9px] text-slate-400 font-bold uppercase tracking-widest truncate">{new Date(post.createdAt).toLocaleDateString('vi-VN')}</span>
          </div>
        </div>
      </div>

      <div className="text-base md:text-lg leading-relaxed mb-6 font-bold text-slate-700 whitespace-pre-wrap tracking-tight">
        <MarkdownText text={post.content} />
      </div>

      {post.aiAnalysis && (
        <div className="p-5 bg-indigo-50/50 rounded-[2rem] mb-6 border border-white/50 flex gap-4 items-start">
           <div className="w-8 h-8 bg-white rounded-[0.8rem] flex items-center justify-center text-indigo-600 shadow-sm shrink-0"><Sparkles size={16} strokeWidth={2.5}/></div>
