const MindMapNode: React.FC<{ node: any; depth?: number }> = ({ node, depth = 0 }) => {
  const [expanded, setExpanded] = useState(true);
  const colors = ['bg-indigo-600', 'bg-purple-500', 'bg-pink-500', 'bg-amber-500'];
  const color = colors[depth % colors.length];

  if (!node) return null;

  return (
    <div className="flex flex-col items-center">
      <div 
        onClick={() => setExpanded(!expanded)}
        className={`px-6 py-3 rounded-2xl text-white font-bold shadow-md cursor-pointer transition-all hover:scale-105 active:scale-95 flex items-center gap-2 ${color} ${depth === 0 ? 'text-xl py-4 px-8 mb-4' : 'text-sm mb-2'}`}
      >
        {node.name || node.root}
        {node.children?.length > 0 && <ChevronDown size={16} className={`transition-transform ${expanded ? 'rotate-180' : ''}`}/>}
      </div>

      {expanded && node.children?.length > 0 && (
        <div className="flex flex-wrap justify-center gap-4 mt-2 border-t-2 border-slate-100 pt-4 relative">
           {/* Simple connecting lines visualization can be complex in CSS-only, using gap/border for structure */}
          {node.children.map((child: any, i: number) => (
            <div key={i} className="flex flex-col items-center">
               <div className="h-4 w-0.5 bg-slate-200 mb-2"></div>
               <MindMapNode node={child} depth={depth + 1} />
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

