import { GoogleGenAI, Type } from "@google/genai";

const FLASH_MODEL = 'gemini-3-flash-preview';

const getAIInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const SYSTEM_CURRICULUM = `Bạn là trợ lý giáo dục cao cấp tại Việt Nam. 
QUY TẮC BẮT BUỘC:
1. Chỉ sử dụng kiến thức từ Chương trình GDPT 2018 (SGK mới).
2. Tuyệt đối không dùng kiến thức chương trình cũ 2006.
3. Cấu trúc câu hỏi trắc nghiệm bám sát định hướng thi tốt nghiệp THPT từ năm 2025.
4. Trả lời cực kỳ ngắn gọn, súc tích, chuyên nghiệp.
5. Giải thích câu hỏi phải rõ ràng, chỉ ra tại sao đúng, tại sao sai.`;

export const generateExamRoadmap = async (grade: string, subject: string): Promise<any> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Tạo lộ trình 5 bước ôn tập môn ${subject} lớp ${grade} (SGK 2018). 
      JSON format: {roadmap: [{id: string, title: string, difficulty: 'theory'|'practice'|'hardcore', topics: string[]}]}`,
      config: {
        systemInstruction: SYSTEM_CURRICULUM,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            roadmap: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  title: { type: Type.STRING },
                  difficulty: { type: Type.STRING },
                  topics: { type: Type.ARRAY, items: { type: Type.STRING } }
                }
              }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (e) {
    return { roadmap: [] };
  }
};

export const generateExamPaper = async (subject: string, grade: string, difficulty: string, count: number = 20): Promise<any[]> => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: FLASH_MODEL,
      contents: `Tạo đúng ${count} câu hỏi trắc nghiệm lớp ${grade} môn ${subject} bám sát SGK 2018, độ khó: ${difficulty}. 
      JSON format: [{question: string, options: [string], answer: string, explanation: string}]`,
      config: {
        systemInstruction: SYSTEM_CURRICULUM,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING }, minItems: 4, maxItems: 4 },
              answer: { type: Type.STRING },
              explanation: { type: Type.STRING }
            }
          }
        }
      }
    });
    const parsed = JSON.parse(response.text || "[]");
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    console.error("Gemini Error:", e);
    return [];
  }
};

export const getTutorResponse = async (msg: string) => {
  const ai = getAIInstance();
  const res = await ai.models.generateContent({
    model: FLASH_MODEL,
    contents: msg,
    config: { systemInstruction: SYSTEM_CURRICULUM }
  });
  return res.text || "Lỗi rồi fen!";
};

export const analyzeStudyImage = async (base64Image: string, prompt: string) => {
  const ai = getAIInstance();
  const res = await ai.models.generateContent({
    model: FLASH_MODEL,
    contents: {
      parts: [
        { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/jpeg' } },
        { text: prompt }
      ]
    },
    config: { systemInstruction: SYSTEM_CURRICULUM }
  });
  return res.text || "Không thể phân tích ảnh.";
};

