// --- MIND MAP COMPONENT (Improved with Tree Lines) ---
const MindMapNode: React.FC<{ node: any; depth?: number; isLast?: boolean }> = ({ node, depth = 0, isLast = false }) => {
  const [expanded, setExpanded] = useState(true);
  const colors = ['bg-indigo-600', 'bg-purple-500', 'bg-pink-500', 'bg-amber-500'];
  const color = colors[depth % colors.length];

  if (!node) return null;

  return (
    <div className="flex flex-col items-center relative">
      <div 
        onClick={() => setExpanded(!expanded)}
        className={`relative z-10 px-6 py-3 rounded-2xl text-white font-bold shadow-md cursor-pointer transition-all hover:scale-105 active:scale-95 flex items-center gap-2 ${color} ${depth === 0 ? 'text-xl py-4 px-8 mb-6' : 'text-sm mb-4'}`}
      >
        {node.name || node.root}
        {node.children?.length > 0 && <ChevronDown size={16} className={`transition-transform ${expanded ? 'rotate-180' : ''}`}/>}
      </div>

      {expanded && node.children?.length > 0 && (
        <div className="flex justify-center gap-8 relative pt-4">
           {/* Connecting Line Vertical from Parent */}
           <div className="absolute top-0 left-1/2 w-0.5 h-4 bg-slate-300 -translate-x-1/2"></div>

           {/* Horizontal Line Connector for Children */}
           {node.children.length > 1 && (
             <div className="absolute top-0 left-[calc(50%/2)] right-[calc(50%/2)] h-0 border-t-2 border-slate-300 w-[calc(100%-4rem)] left-8"></div>
           )}

           {node.children.map((child: any, i: number) => (
            <div key={i} className="flex flex-col items-center relative">
               {/* Vertical Line to Child */}
               <div className="w-0.5 h-4 bg-slate-300 absolute -top-4"></div>
               <MindMapNode node={child} depth={depth + 1} isLast={i === node.children.length - 1} />
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

// --- FLASHCARD COMPONENT ---
const FlashcardViewer: React.FC<{ cards: any[] }> = ({ cards }) => {
  const [index, setIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);

  const nextCard = () => {
    setIsFlipped(false);
    setTimeout(() => setIndex((index + 1) % cards.length), 200);
  };

  const prevCard = () => {
    setIsFlipped(false);
    setTimeout(() => setIndex((index - 1 + cards.length) % cards.length), 200);
  };

  const downloadDeck = () => {
    const csvContent = "Front,Back\n" + cards.map(c => `"${c.front}","${c.back}"`).join("\n");
    downloadAsFile(csvContent, "flashcards.csv");
  };

  if (!cards.length) return <div>Không có thẻ nào.</div>;

  return (
    <div className="flex flex-col items-center gap-6 w-full max-w-md mx-auto">
      <div className="perspective-1000 w-full aspect-[3/2] cursor-pointer group" onClick={() => setIsFlipped(!isFlipped)}>
        <div className={`relative w-full h-full transition-all duration-500 transform-style-3d ${isFlipped ? 'rotate-y-180' : ''}`}>
          {/* Front */}
          <div className="absolute inset-0 backface-hidden bg-white border-2 border-slate-100 rounded-[2rem] shadow-xl flex flex-col items-center justify-center p-8 text-center">
            <span className="absolute top-4 left-4 text-[10px] font-black uppercase tracking-widest text-slate-400">Front</span>
            <p className="text-xl font-black text-slate-800">{cards[index].front}</p>
            <div className="absolute bottom-4 right-4 text-slate-300"><RotateCw size={16}/></div>
          </div>
          {/* Back */}
          <div className="absolute inset-0 backface-hidden bg-indigo-600 rounded-[2rem] shadow-xl flex flex-col items-center justify-center p-8 text-center rotate-y-180 text-white">
            <span className="absolute top-4 left-4 text-[10px] font-black uppercase tracking-widest text-indigo-300">Back</span>
            <p className="text-lg font-bold">{cards[index].back}</p>
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between w-full">
        <button onClick={prevCard} className="p-3 bg-white border border-slate-200 rounded-xl hover:bg-slate-50"><ArrowLeft size={20}/></button>
        <span className="font-black text-slate-400 text-xs tracking-widest">{index + 1} / {cards.length}</span>
        <button onClick={nextCard} className="p-3 bg-white border border-slate-200 rounded-xl hover:bg-slate-50"><ArrowRight size={20}/></button>
      </div>

      <button onClick={downloadDeck} className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-indigo-600 hover:underline">
        <Download size={14}/> Tải CSV (Anki)
      </button>

      <style>{`
        .perspective-1000 { perspective: 1000px; }
        .transform-style-3d { transform-style: preserve-3d; }
        .backface-hidden { backface-visibility: hidden; }
        .rotate-y-180 { transform: rotateY(180deg); }
      `}</style>
    </div>
  );
};

