      Trả về JSON: { "score": number, "feedback": "Nhận xét chi tiết (điểm mạnh, điểm yếu)", "improvements": "Gợi ý cách viết lại hay hơn (cụ thể)" }`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            feedback: { type: Type.STRING },
            improvements: { type: Type.STRING }
          }
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (e) {
    return null;
