const AMBIENT_SOUNDS = [
  { id: 'rain', name: 'Mưa Rơi', icon: CloudRain, url: 'https://www.soundjay.com/nature/rain-01.mp3' },
  { id: 'wind', name: 'Gió Ngàn', icon: Wind, url: 'https://www.soundjay.com/nature/wind-01.mp3' },
