          { id: AppTab.MISSION, icon: Rocket, label: 'Chiến Dịch Sở GD' },
          { id: AppTab.TUTOR, icon: Bot, label: 'Gia sư AI' },
          { id: AppTab.FOCUS, icon: Clock, label: 'Phòng Tập Trung' },
          { id: AppTab.TOOLS, icon: LayoutGrid, label: 'Kho Đề & Công Cụ' },
